/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-C4dIk\":[\"Sudoku yang membutuhkan rantai paksa jarang ada dan mahal untuk dicari sesuai permintaan, jadi Suuudokuuu membawa korpus bawaan yang sudah diperiksa oleh solver exact-cover Dancing Links dan solver bitmask, dinilai, dan disaring menjadi sudoku rantai paksa sebelum dikemas.\"],\"-Elizp\":[\"Ketika irisan mulai terasa otomatis, naiklah ke <0>buklet sudoku Sulit cetak</0> untuk pola fish dan wing. Turunlah ke <1>sudoku mudah cetak</1> untuk pemanasan teknik tunggal, atau mainkan Sedang di layar pada <2>halaman sudoku sedang</2>.\"],\"-bYKwe\":[\"Termasuk Everest (SE 11,9), Platinum Blonde (SE 10,9), dan AI Escargot (SE 10,6).\"],\"-iJ7nh\":[[\"clueCount\"],\" angka awal dari 81 sel, bisa diselesaikan hanya dengan sel kosong terakhir dan tunggal telanjang.\"],\"-vAdwL\":[\"Teknik\"],\"0Ktk6B\":[\"Diperbarui <0>\",[\"formattedDate\"],\"</0>\"],\"0L9JZJ\":[\"Berapa banyak sudoku dalam PDF sudoku Mudah cetak?\"],\"0MRfHz\":[\"Sudoku Tak Terhingga\"],\"0RoXsf\":[\"Apakah PDF sudoku Mimpi buruk cetak gratis?\"],\"0Sy9Gs\":[\"Berapa banyak sudoku dalam PDF sudoku Neraka cetak?\"],\"0bpi83\":[\"Buklet sudoku cetak berdasarkan tingkat kesulitan\"],\"0r_rbI\":[\"Apakah \",[\"SITE_NAME\"],\" memiliki iklan?\"],\"0zmlwH\":[\"Unduh \",[\"title\"],\" (PDF)\"],\"18cwop\":[\"<0>Mudah</0> — \",[\"easyClueCount\"],\" angka awal, dijamin membutuhkan minimal satu tunggal tersembunyi dan tidak lebih sulit dari itu.\"],\"1KnfS2\":[\"Berapa banyak angka awal sudoku Mimpi buruk?\"],\"1Lvcgc\":[\"Sudoku 1 dari buklet Mimpi buruk, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"1SEI1B\":[\"Ini adalah tingkat buatan tersulit di Suuudokuuu, diukur pada SE \",[\"seRatingRange\"],\" dari sampel \",[\"sampleSize\"],\" sudoku. Setiap sudokunya membutuhkan logika rantai atau pewarnaan di atas pola fish dan wing yang sudah dibutuhkan Sulit.\"],\"1ZWQlV\":[\"Cara mencetak sudoku ini\"],\"1ZluOW\":[\"Mengapa kertas membantu untuk rantai\"],\"1aVkEA\":[\"Teknik irisan bekerja pada tumpang tindih antara satu kotak dan satu baris atau kolom. Pasangan atau tripel penunjuk menemukan angka yang terbatas pada dua atau tiga sel sebuah kotak yang semuanya berada di satu garis, lalu menghapusnya dari sisa garis itu; reduksi kotak-baris adalah bayangan cerminnya, bekerja dari sebuah garis kembali ke sebuah kotak. Pasangan telanjang dan tersembunyi adalah pintu masuk ke penalaran subset: dua sel yang berbagi tepat dua kandidat, atau dua angka yang hanya muat di tepat dua sel dalam sebuah unit, keduanya mengunci dua sel itu dari yang lain di unit tersebut. Tidak satu pun menempatkan angka secara langsung — hanya menghapus kandidat — tetapi dengan \",[\"clueCount\"],\" angka awal, sudoku Sedang selalu punya setidaknya satu yang menunggu, dan biasanya itu cukup untuk membuka tunggal telanjang baru satu atau dua langkah kemudian. Tingkat ini juga dibatasi di ujung lainnya: tidak ada yang membutuhkan fish, wing, atau rantai, karena sudoku yang membutuhkannya dinaikkan ke Sulit.\"],\"27Qok0\":[\"Tidak ada sudoku di tingkat ini yang membutuhkan fish, wing, atau rantai — sudoku yang membutuhkannya dinaikkan ke Sulit.\"],\"2Dg4GX\":[\"Seberapa sulit sebenarnya\"],\"2Lb_CG\":[\"Cari tunggal tersembunyi\"],\"2N-XHb\":[\"Sudoku untuk lansia\"],\"2gnUkr\":[\"Pemula\"],\"2wuXBd\":[\"Hal pertama yang perlu diperiksa adalah apakah ada kotak, baris, atau kolom yang hanya kekurangan satu angka. Jika delapan dari sembilan sel dalam sebuah unit sudah terisi, sel kesembilan harus diisi angka yang masih hilang dari unit itu — tanpa membandingkan kandidat, cukup dengan pengurangan.\"],\"3-aLmy\":[\"Ya. Keduanya ada di kumpulan Tak Terhingga, bersama Platinum Blonde dan Golden Nugget. Setiap permainan mengacak angka, baris, dan kolom, jadi grid terlihat berbeda setiap kali sementara sudokunya tetap sama.\"],\"35wRk8\":[\"Ini tingkat termudah yang ditawarkan Suuudokuuu, dan generator menjaminnya: sebuah sudoku hanya dirilis sebagai Pemula setelah solver yang dibatasi pada sel kosong terakhir dan tunggal telanjang berhasil menyelesaikannya. Sampel kami diukur pada SE \",[\"seRatingRange\"],\", tanpa pelacakan kandidat dan tanpa risiko terpaksa menebak.\"],\"367Cn7\":[\"Teknik apa yang dibutuhkan buklet sudoku Mudah?\"],\"3DJmkH\":[\"Mesin teknik kami sepakat bahwa sudoku ini berada di luar jangkauannya. Mesin ini mengenal setiap pola di <0>indeks teknik</0>, sampai <1/> dan <2/>, dan tetap tidak bisa menyelesaikan satu pun sudoku Tak Terhingga sendirian. Itu tidak berarti sudoku ini butuh tebakan; artinya sudoku ini butuh jaring paksa yang lebih panjang daripada yang diimplementasikan mesin. Petunjuk dimatikan secara bawaan di Mimpi buruk, Neraka, dan Tak Terhingga, dan sebuah pengaturan menyalakannya kembali jika Anda ingin bantuan mesin sejauh kemampuannya.\"],\"3SwmIF\":[\"Saat Anda memulai permainan Tak Terhingga, aplikasi memilih salah satu sudoku itu dan menyamarkannya. Angkanya dilabeli ulang, baris diacak dalam bandnya, kolom dalam stack-nya, begitu pula band dan stack itu sendiri, dan kadang grid dicerminkan menurut diagonalnya. Tidak satu pun mengubah logika atau peringkatnya, jadi Everest yang Anda mainkan tetap Everest, hanya saja tidak tampak seperti gambar di bawah.\"],\"3a3AKD\":[\"Apakah buklet sudoku Pemula cetak ini gratis?\"],\"3c-rtT\":[\"Unduh di App Store\"],\"3l9jCt\":[\"Berapa banyak tingkat kesulitan sudoku yang dimiliki Suuudokuuu?\"],\"3m4lq2\":[\"Fish mudah terlewat di layar yang hanya menampilkan beberapa sel sekaligus, karena polanya terletak pada tempat sebuah angka bisa berada di dua, tiga, atau empat garis penuh pada saat yang sama. Pada grid cetak penuh, Anda bisa menandai posisi sisa angka itu di sepanjang kolom dan membaca bentuknya langsung dari halaman. Wing membutuhkan sudut pandang sebaliknya — beberapa sel bivalue yang saling melihat di seluruh grid — dan melingkarinya dengan pensil membuat tumpang tindihnya jelas terlihat. Karena kedua keluarga ini mudah salah diterapkan pada beberapa kali pertama, memeriksa pekerjaan Anda dengan halaman kunci jawaban di bagian belakang layak dilakukan setiap kali sampai bentuknya terbiasa.\"],\"4-X0DJ\":[\"Dapatkan di Google Play\"],\"4DuWbm\":[\"<0>Aturan baris.</0> Setiap dari sembilan baris harus berisi angka 1 sampai 9, masing-masing tepat satu kali.\"],\"4EAgIb\":[\"Grid Sudoku Kosong\"],\"4HAVnv\":[\"Setiap sudoku di buklet ini berasal dari korpus bawaan yang diperiksa Suuudokuuu dengan dua algoritma penyelesaian independen — solver exact-cover Dancing Links dan solver bitmask berbasis typed-array — sebelum dirilis, sehingga setiap grid terkonfirmasi memiliki tepat satu solusi. Korpus ini diambil dari katalog 17 angka awal proyek tdoku dan daftar sudoku sulit top1465 magictour, dan setiap sudoku juga diselesaikan secara logis dan dinilai pada skala SE saat korpus dikemas. Hanya sudoku yang langkah tersulitnya adalah rantai paksa yang lolos; apa pun yang runtuh oleh rantai, pewarnaan, atau AIC dibuang, karena jumlah angka awal maupun daftar sumber saja tidak cukup untuk menjamin sebuah sudoku Neraka. Setiap sudoku yang lolos tetap bisa diselesaikan pada tangga teknik kami tanpa menebak, jadi setiap sudoku di sini dijamin bisa diselesaikan dengan logika sebelum Anda memegang pensil.\"],\"4NMPvd\":[\"Teknik apa yang saya butuhkan untuk sudoku Sulit?\"],\"4apI84\":[\"Sudoku cetak besar, siap cetak\"],\"4gZ5Vw\":[\"Gratis dan sumber terbuka di bawah lisensi \",[\"SITE_LICENSE\"],\". Tanpa iklan, tanpa akun, tanpa pelacakan di dalam game — baca <0>alasannya</0> atau telusuri <1>kode sumber lengkap di GitHub</1>. Apple dan logo Apple adalah merek dagang Apple Inc., terdaftar di AS dan negara lain. App Store adalah merek layanan Apple Inc. Google Play dan logo Google Play adalah merek dagang Google LLC.\"],\"52_TbA\":[\"Memverifikasi fish dan wing di kertas\"],\"57DMl6\":[\"Rantai sudah mulai terasa? <0>Buklet sudoku Neraka cetak</0> adalah tingkat terakhir, tempat setiap sudoku membutuhkan rantai paksa. Mundurlah ke <1>sudoku sulit cetak</1> untuk fish dan wing saja, atau mainkan Mimpi buruk di layar pada <2>halaman sudoku mimpi buruk</2>.\"],\"5D6pgW\":[\"Sebuah sudoku Mudah dari generator yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"5EmtkG\":[\"Apakah PDF sudoku Neraka cetak gratis?\"],\"5YPKNQ\":[\"Siapa yang menilai sudoku ini?\"],\"5a2b2H\":[\"Apakah ini sudoku 17 angka awal?\"],\"5tWoLs\":[\"Belajar sudoku\"],\"64gfbY\":[\"Mainkan Sudoku Pemula sekarang\"],\"6JHmjr\":[\"Ya. Setiap grid diperiksa oleh solver exact-cover Dancing Links dan solver bitmask sebelum dirilis, dan masing-masing memiliki tepat satu solusi.\"],\"6Y2zqp\":[\"Apakah sudoku Sedang sulit?\"],\"6i2Miv\":[\"Mimpi buruk hanya menyisakan \",[\"clueCount\"],\" angka awal, dan inilah buklet yang membuat halaman cetak benar-benar berguna. Setiap sudoku di dalamnya diuji dengan solver yang sudah menguasai setiap fish dan wing — termasuk <0>swordfish</0> dan <1>XY-Wing</1> — dan hanya disimpan karena solver itu buntu. Yang menyelesaikannya adalah penalaran rantai, dan rantai jauh lebih mudah dibangun di kertas, tempat Anda bisa menuliskan tautannya dengan pensil dan mengikutinya, daripada di layar yang sempit. Sampel kami berisi \",[\"sampleSize\"],\" sudoku dengan tingkat SE \",[\"seRatingRange\"],\".\"],\"6mE7Xy\":[\"Irisan atau pasangan baru terlihat setelah Anda bisa melihat semua kandidat yang tersisa di satu baris, kolom, atau kotak sekaligus, itulah sebabnya kertas benar-benar lebih membantu di sini daripada layar: tulis angka kecil di sudut setiap sel kosong, lalu pindai satu garis untuk mencari angka yang terkurung di satu kotak, atau dua sel yang berbagi tepat dua kandidat. Tidak satu pun dari kedua pola ini menempatkan angka dengan sendirinya — masing-masing hanya menghapus kandidat — jadi bersiaplah menandai beberapa eliminasi sebelum tunggal telanjang baru benar-benar muncul. Bekerja dengan pensil, bukan pulpen, berarti tanda yang salah bisa dihapus tanpa masalah.\"],\"6pYHox\":[\"<0>Pemula.</0> Bisa diselesaikan hanya dengan sel kosong terakhir dan tunggal telanjang.\"],\"6tfEbk\":[\"Setiap sudoku diperiksa memiliki tepat satu solusi oleh dua algoritma penyelesaian yang independen.\"],\"6yBCvI\":[\"Apa yang membuat sudoku Mimpi buruk\"],\"6z6usR\":[\"Ingin sudoku rekor di kertas? Unduh <0>PDF sudoku Tak Terhingga cetak</0>. Belum siap? Mundurlah ke <1>Sudoku Neraka</1>, tempat setiap sudoku membutuhkan rantai paksa tetapi masih dalam jangkauan tangga teknik kami. Baca kisah di balik Everest dan AI Escargot di halaman <2>sudoku tersulit</2>, bandingkan setiap tingkat di hub <3>Tingkat kesulitan sudoku</3>, atau kembali ke <4>beranda</4>.\"],\"6zwJ5l\":[\"Mudah berada di dasar skala SE (Sudoku Explainer) bersama Pemula: sampel kami berisi \",[\"sampleSize\"],\" sudoku dengan SE \",[\"seRatingRange\"],\". Kedua tingkat berbagi rentang yang sama karena SE memberi nilai 1,5 untuk tunggal tersembunyi, lebih rendah daripada 2,3 untuk tunggal telanjang — jadi teknik yang menentukan Mudah, menurut skala itu, lebih murah daripada yang menentukan Pemula. Yang benar-benar berubah adalah tempat Anda harus melihat: tunggal telanjang dibaca dari satu sel, tunggal tersembunyi dari seluruh unit. Cocok untuk pemain yang sudah menyelesaikan beberapa sudoku Pemula dan ingin sudoku yang jelas lebih lama diselesaikan.\"],\"75Y3_I\":[\"Apakah AI Escargot ada di buklet cetak?\"],\"7A3Fmz\":[\"Kesulitan lebih mudah\"],\"7Y8jud\":[\"Mainkan Sudoku Sulit sekarang\"],\"7Z44bB\":[\"Sudah lancar mengenali fish dan wing? Naiklah ke <0>buklet sudoku Mimpi buruk cetak</0> untuk rantai dan pewarnaan. Mundurlah ke <1>sudoku sedang cetak</1> untuk irisan dan subset saja, atau mainkan Sulit di layar pada <2>halaman sudoku sulit</2>.\"],\"7hktsm\":[\"Memulai\"],\"7lhqPv\":[\"Ringkasan singkat\"],\"7r6sCa\":[\"Ukuran teks\"],\"7z1tpm\":[\"Tidak. Mode catatan di aplikasi melacak kandidat untuk Anda, memperbaruinya otomatis saat Anda menempatkan angka, dan memungkinkan Anda membatalkan kesalahan tanpa menghapus.\"],\"83yMJR\":[\"Setiap tingkat dari Pemula sampai Tak Terhingga kini punya panduannya sendiri, yang menguraikan persis apa yang membedakan satu tingkat dari berikutnya — jumlah angka awal, teknik yang dibutuhkan, dan penilaian jujur seberapa sulit masing-masing. Mulailah di hub <0>Tingkat kesulitan sudoku</0>, atau lihat perbandingannya dengan <1>sudoku tersulit</1> yang pernah dipublikasikan.\"],\"8GGOmr\":[\"Grid yang selesai memenuhi ketiga aturan itu sekaligus. Tumpang tindih itulah yang membuat sudoku bisa diselesaikan dengan logika: angka yang sudah tersingkir oleh baris, kolom, dan kotaknya tidak punya tempat lagi, dan itulah dasar hampir semua teknik penyelesaian. Setiap teknik bernama di situs ini, dari tunggal paling sederhana sampai rantai terpanjang, pada dasarnya hanyalah cara yang lebih efisien untuk melacak tumpang tindih itu di banyak sel sekaligus, bukan satu sel per satu sel.\"],\"8HgdwA\":[[\"mediumClueCount\"],\" angka awal, dijamin buntu di teknik tunggal dan baru terpecahkan dengan irisan dan subset. Lihat <0>halaman sudoku sedang</0> untuk memainkannya secara digital.\"],\"8bwpsb\":[\"Sudoku online gratis berarti memainkan teka-teki angka klasik 9×9 di peramban atau aplikasi tanpa pembelian, batas pemasangan, atau paywall, dan \",[\"SITE_NAME\"],\" adalah implementasi gratis dan sumber terbuka darinya — tujuh tingkat kesulitan dari Pemula sampai Tak Terhingga, panduan yang menjelaskan teknik, tanpa iklan dan tanpa pelacakan di dalam game. Mainkan di web atau pasang aplikasinya, lalu pertahankan rentetan dan statistik yang sama di mana pun. Lihat <0>mengapa \",[\"SITE_NAME\"],\" dibuat seperti ini</0> untuk penjelasan lengkap yang bisa diverifikasi.\"],\"8hKEc0\":[\"FAQ Sudoku Mimpi buruk\"],\"8j_b89\":[\"Mimpi buruk dibatasi sampai AIC — sudoku yang bertahan melawannya berada di luar jangkauan tingkat yang dibuat otomatis.\"],\"8ko6ZU\":[\"<0>Neraka</0> — dijamin buntu di AIC dan membutuhkan rantai paksa, diambil dari korpus bawaan yang terverifikasi, bukan dibuat sesuai rentang teknik.\"],\"8wCnRb\":[\"Sudoku dicetak persis seperti saat dipublikasikan, tanpa diacak ulang, sehingga Anda bisa membandingkan grid Anda dengan aslinya yang dibahas di halaman <0>sudoku tersulit</0>. Sudoku dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman dengan ruang untuk satu set lengkap tanda pensil, yang akan Anda butuhkan: di tingkat ini kebanyakan penyelesai menuliskan setiap kandidat dan menguji rantai di lembar terpisah. Halaman terakhir memuat grid yang sudah terselesaikan, sehingga Anda bisa memeriksa rangkaian penalaran yang panjang tanpa harus menyelesaikannya dulu.\"],\"92GEeo\":[\"Ingin pemanasan dulu? <0>Buklet sudoku Neraka cetak</0> berisi sudoku rantai paksa yang sulit tetapi masih dalam jangkauan tangga teknik kami. Lebih suka layar? Mainkan sudoku rekor yang sama di <1>halaman sudoku tak terhingga</1>, tempat setiap permainan mengacak ulang grid, atau telusuri setiap buklet di <2>hub sudoku cetak</2>.\"],\"93EF2k\":[\"Berapa banyak angka awal sudoku Neraka?\"],\"9AexDe\":[\"Sudoku yang bisa diselesaikan oleh solver dengan sel kosong terakhir dan tunggal telanjang saja akan ditolak karena terlalu mudah untuk tingkat ini.\"],\"9COcEj\":[\"Pola fish: X-Wing, swordfish, jellyfish, dan varian finned serta sashimi-nya. Pola wing: XY-Wing, XYZ-Wing, dan W-Wing.\"],\"9TF92W\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Mudah dengan SE \",[\"seRatingRange\"],\".\"],\"9e_cYH\":[\"FAQ Sudoku Pemula\"],\"9qTjdv\":[\"Berapa banyak sudoku dalam PDF sudoku Sedang cetak?\"],\"9rfjS-\":[[\"PRINTABLE_LARGE_PRINT_PAGE_COUNT\"],\" halaman\"],\"AKA0Xn\":[\"Teknik apa yang dibutuhkan buklet Sulit ini?\"],\"AV85q_\":[[\"clueCount\"],\" angka awal dari 81 sel, diselesaikan dari awal sampai akhir dengan sel kosong terakhir, tunggal telanjang, dan tunggal tersembunyi.\"],\"AdsNQX\":[\"Ya. Sampel kami mengukur Neraka pada SE \",[\"hellSeRatingRange\"],\", dan setiap sudoku Tak Terhingga memiliki peringkat terpublikasi antara \",[\"lowestRatingLabel\"],\" dan \",[\"highestRatingLabel\"],\". Sudoku Neraka masih tunduk pada tangga teknik kami; sudoku Tak Terhingga tidak.\"],\"AfMtNM\":[\"FAQ Sudoku Neraka\"],\"Ak9Eh5\":[\"Sebuah sudoku Sulit dari generator yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"B-pBHn\":[\"Rantai tingkat kesulitan sudoku\"],\"BJrGt8\":[\"Tepat satu teknik. Setiap sudoku Pemula bisa diselesaikan dengan sel kosong terakhir dan tunggal telanjang; setiap sudoku Mudah terbukti tidak bisa, dan membutuhkan minimal satu tunggal tersembunyi untuk memecahkan kebuntuan.\"],\"BZz12Q\":[\"Cetak\"],\"C1_WBQ\":[\"Sudoku adalah teka-teki logika yang dimainkan di grid 9×9, terbagi menjadi sembilan kotak 3×3. Tujuannya mengisi setiap sel kosong dengan angka 1 sampai 9 sehingga tidak ada angka yang berulang di baris, kolom, atau kotak mana pun. Sudoku yang tersusun baik selalu dimulai dengan beberapa sel yang sudah terisi — angka awal — dan selalu memiliki tepat satu solusi valid yang bisa dicapai hanya dengan logika, tanpa menebak.\"],\"C4kvBI\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Neraka dengan SE \",[\"seRatingRange\"],\", dengan <0/> sebagai langkah tersulit yang paling sering muncul.\"],\"CA7v0X\":[\"Beberapa grid ini dimulai dengan hanya \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" angka awal dan tampak hampir kosong sekilas — \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman dengan ukuran sel yang lega khusus agar ada ruang untuk melacak kandidat secara manual sepanjang rantai yang panjang. Halaman terakhir memuat grid yang sudah terselesaikan, yang hampir wajib di tingkat ini: memverifikasi rantai eliminasi dengan mata telanjang itu lambat, dan kunci cetak memungkinkan Anda memastikan keadaan akhir tanpa menurunkan ulang seluruh jalurnya.\"],\"CAD1qm\":[\"Rantai mengikuti urutan tautan kuat dan lemah yang berselang-seling, dimulai dari sebuah kandidat dan bernalar ke arah luar sampai terbukti ada eliminasi atau penempatan, apa pun cabang yang ternyata benar. X-Chain bekerja dengan satu angka; XY-Chain menyusuri jalur sel bivalue. Pewarnaan sederhana memberi dua warna bergantian pada jaringan tautan kuat dari satu angka dan menghapus setiap kandidat yang melihat kedua warna itu, sedangkan AIC menggeneralisasi seluruh keluarga ini, dengan angka dan jenis sel yang bercampur sepanjang satu rantai tak terputus. Neraka dimulai tepat ketika semua itu habis. Rantai paksa mengandaikan sebuah kandidat, kemungkinan isi sebuah sel, atau penempatan sebuah wilayah, menelusuri setiap konsekuensinya, dan hanya menyimpan apa yang berlaku di setiap cabang — halaman <0>Nishio</0>, <1>sel</1>, dan <2>rantai paksa region</2> menguraikan masing-masing satu contoh. Sebuah sudoku masuk ke korpus Neraka hanya jika langkah tersulit pada jalur dengan peringkat optimal adalah rantai paksa, dan hanya jika tangga kami masih bisa menyelesaikannya, jadi tidak ada sudoku Neraka yang meminta Anda menebak.\"],\"CLPF0E\":[\"Peringkat ini adalah nilai yang dipublikasikan penilai independen, bukan hasil pengukuran kami.\"],\"ChsZzh\":[[\"hardClueCount\"],\" angka awal, dijamin buntu di subset dan baru terpecahkan dengan pola fish dan wing. Lihat <0>halaman sudoku sulit</0> untuk memainkannya secara digital.\"],\"DE2rA9\":[\"Angka awal versus kesulitan\"],\"DE6q1A\":[\"Ya, secara konstruksi. Mimpi buruk berhenti di AIC, dan tidak ada sudoku Neraka yang bisa diselesaikan dengan apa pun yang diizinkan Mimpi buruk. Sampel kami mengukur Neraka pada SE \",[\"hellSeRatingRange\"],\" dan Mimpi buruk pada SE \",[\"nightmareSeRatingRange\"],\".\"],\"DFi0Zn\":[\"Lebih sulit daripada apa pun di aplikasi, dengan selisih yang jauh. Sampel kami berisi \",[\"sampleSize\"],\" sudoku <0>Neraka</0> dengan SE \",[\"hellSeRatingRange\"],\"; Tak Terhingga dimulai dari \",[\"lowestRatingLabel\"],\". Peringkat Tak Terhingga bukan hasil pengukuran kami. Penilai Suuudokuuu hanya menilai tangga SE sampai rantai paksa dan jaring paksa, dan melaporkan \",[\"SE_RATING_CEILING\"],\" dengan tanda batas atas di atas itu, jadi untuk sudoku ini kami mengutip angka yang dipublikasikan penilai independen, seperti yang dijelaskan <1>panduan peringkat kesulitan</1>.\"],\"DIr2XR\":[\"Irisan: pasangan penunjuk, tripel penunjuk, reduksi kotak-baris. Subset: pasangan telanjang, pasangan tersembunyi.\"],\"DRVEbn\":[\"FAQ Sudoku Neraka Cetak\"],\"DRleO8\":[\"<0>Sel Kosong Terakhir</0> — langkah paling sederhana, yaitu mengisi sel kosong terakhir dalam satu unit.\"],\"D_b_9m\":[\"FAQ Sudoku Mudah\"],\"DgPHNt\":[\"Fish yang hampir lengkap: baris atau kolomnya membentuk X-Wing atau <0>swordfish</0> kecuali untuk satu atau dua kandidat tambahan, yaitu fin. Eliminasinya tetap berlaku, tetapi hanya di sel yang terlihat oleh fish sekaligus fin.\"],\"DjGWF0\":[\"Tuliskan setiap kandidat yang tersisa untuk sel kosong yang masih ada, lalu telusuri indeks teknik berdasarkan urutan kesulitan untuk terus menyelesaikannya.\"],\"Drd4wO\":[\"Sebuah angka yang terbatas pada dua sel dalam satu kotak yang juga berada di baris atau kolom yang sama. Angka itu lalu bisa dihapus dari sisa baris atau kolom tersebut, karena salah satu dari dua sel itu pasti berisi angka tersebut.\"],\"DvhSrh\":[[\"clueCount\"],\" angka awal dari 81 sel, dijamin membutuhkan tunggal tersembunyi dan tidak lebih sulit dari itu.\"],\"E5Cz6q\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku\"],\"ER15gL\":[\"Sebuah sudoku rekor Tak Terhingga dari kumpulan pilihan yang sama dengan yang dipakai aplikasi, dengan susunan yang diacak ulang. Mainkan langsung di sini.\"],\"ETZyJl\":[\"Tujuh tingkat kesulitan dari Pemula lewat Neraka sampai Tak Terhingga, tingkat teratas yang menyajikan sudoku rekor seperti Everest dan AI Escargot\"],\"EYQUVy\":[\"<0>Sulit.</0> Selalu buntu di subset dan selalu terpecahkan dengan fish atau wing.\"],\"EYVt4M\":[\"Ukuran teks terbesar\"],\"EyMkmB\":[\"Apa tingkat kesulitan Sudoku yang paling mudah?\"],\"F_APxp\":[\"Sudoku offline gratis untuk iOS, Android, dan web\"],\"FfmJIb\":[\"Apakah PDF sudoku Sedang cetak gratis?\"],\"Fgi0TQ\":[\"Tidak ada sudoku di buklet ini yang membutuhkan fish, wing, atau rantai.\"],\"Fv02gG\":[\"Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku Sulit dengan tingkat SE \",[\"seRatingRange\"],\", dengan <0/> sebagai langkah tersulit yang paling sering muncul — angka yang diukur langsung oleh <1>panduan peringkat kesulitan sudoku</1>, bukan sekadar diasumsikan. \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku di sini dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman dengan ruang untuk menandai kandidat, dan grid yang sudah terselesaikan di halaman penutup memungkinkan Anda memastikan bahwa eliminasi fish benar-benar berlaku.\"],\"G70CkD\":[\"Berapa banyak angka awal sudoku Sedang?\"],\"GCBW83\":[\"Selesaikan penempatan termurah lebih dulu: sel kosong terakhir, lalu tunggal telanjang, lalu tunggal tersembunyi.\"],\"GOSVU9\":[\"Sudoku Sedang memiliki \",[\"clueCount\"],\" angka awal dan dijamin buntu di teknik tunggal serta baru terpecahkan dengan irisan atau subset.\"],\"GRoZ7D\":[\"Sudoku Neraka\"],\"GU9wm2\":[\"Bisakah dipakai di kelas?\"],\"G_3WRn\":[\"Apakah bisa dimainkan offline?\"],\"GalvXV\":[\"Tak Terhingga adalah tingkat Suuudokuuu di atas Neraka: kumpulan pilihan sudoku tersulit yang pernah dipublikasikan, grid rekor yang masih diperdebatkan komunitas penyelesai, siap dimainkan gratis. Setiap sudoku Tak Terhingga adalah sudoku yang dikenal dengan peringkat Sudoku Explainer (SE) terpublikasi minimal \",[\"minimumRatingLabel\"],\" — Everest karya Arto Inkala, Platinum Blonde, AI Escargot, Golden Nugget, dan \",[\"additionalPuzzleCount\"],\" lainnya — dan diperiksa memiliki solusi tunggal sebelum dirilis. Inilah sudoku yang diuraikan panduan <0>sudoku tersulit</0> kami; Tak Terhingga adalah tempat memainkannya.\"],\"GeGHUl\":[\"Setiap PDF diatur ke US Letter dan digambar dengan garis dan teks vektor, jadi tercetak tajam di ukuran apa pun. Buka berkasnya, cetak dengan skala 100% (bukan “fit to page”, yang bisa mendistorsi grid di beberapa printer), dan cetak satu sisi jika Anda ingin kunci jawaban berada di lembar terpisah dari sudokunya.\"],\"Gfmra_\":[\"Sebuah sudoku Mudah untuk memulai. Mainkan langsung di sini, atau pilih salah satu dari tujuh tingkat kesulitan di aplikasi.\"],\"Gu8Ueq\":[\"Apa yang membuat sudoku Tak Terhingga\"],\"GzaiWG\":[\"FAQ cara bermain Sudoku\"],\"H47ltZ\":[\"Bagaimana cara mencetak sudoku ini?\"],\"HCMGUO\":[\"Apakah kita pernah harus menebak?\"],\"HDn1fw\":[[\"clueCount\"],\" angka awal dari 81 sel, dijamin membutuhkan minimal satu pola fish atau wing di atas semua subset.\"],\"HJEQpI\":[\"Berkisar dari \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\". Neraka tidak memakai jumlah angka awal untuk memilih sudokunya; sebuah sudoku memenuhi syarat karena membutuhkan rantai paksa, berapa pun jumlah angka awalnya.\"],\"HPogd9\":[\"Mengapa kertas direkomendasikan untuk sudoku berbasis rantai?\"],\"HQCVxF\":[\"Apakah Pemula tingkat yang tepat untuk anak-anak atau pemain pertama kali?\"],\"HSXkrR\":[\"Sudoku yang tersusun baik selalu memiliki tepat satu solusi dan tidak pernah membutuhkan tebakan.\"],\"HV3Yoi\":[\"Sudoku Sulit\"],\"Ht078b\":[\"Sudoku 1 dari buklet Sedang, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"I11j00\":[\"Mimpi buruk adalah tingkat ahli Suuudokuuu — yang di aplikasi lain disebut very hard atau expert. Sudoku Mimpi buruk hanya memiliki \",[\"clueCount\"],\" angka awal dari 81 sel, dan inilah tingkat ketika pola terbatas tidak lagi cukup: setiap sudoku di sini sudah diperiksa dengan solver yang menguasai setiap fish dan setiap wing sampai <0>W-Wing</0>, dan hanya diberi label Mimpi buruk karena solver itu buntu. Menyelesaikannya membutuhkan penalaran rantai — <1>X-Chain</1>, <2>XY-Chain</2>, <3>pewarnaan sederhana</3>, dan <4>AIC</4>, rantai inferensi berselang-seling yang menggeneralisasi ketiga teknik lainnya.\"],\"I3XIAf\":[\"Lebih suka layar? Mainkan Suuudokuuu sekarang\"],\"IANVSf\":[\"Tidak. Tidak ada iklan di mana pun dan tidak ada pelacakan di dalam game; situs web ini hanya memakai analitik halaman anonim tanpa cookie.\"],\"IB9N-i\":[\"Apa bedanya angka awal dan kandidat?\"],\"IFKUNe\":[\"Tidak perlu catatan pensil, logika eliminasi, ataupun tebakan untuk sudoku mana pun di buklet ini.\"],\"IOgWqm\":[\"Memuat papan…\"],\"I_WAm2\":[\"Ya. Setelah dipasang, \",[\"SITE_NAME\"],\" membuat dan menyelesaikan sudoku sepenuhnya di perangkat Anda, jadi dimainkan sama saja tanpa koneksi.\"],\"IjDWTu\":[\"Bagaimana sudoku diverifikasi\"],\"IlAsp5\":[\"Tingkat kesulitan sudoku mana yang sebaiknya saya mulai?\"],\"IqBsZ0\":[\"Ya. PDF diunduh gratis, tanpa akun dan tanpa tanda air, dan menyertakan kunci jawaban lengkap untuk setiap sudoku.\"],\"IrAE3z\":[\"Solver\"],\"Iu83qB\":[\"Sudoku 1 dari buklet Pemula, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"JBdo3D\":[\"FAQ tingkat kesulitan sudoku\"],\"JJoC7U\":[\"Apa yang membuat sudoku Sulit\"],\"Jrqsp5\":[\"Tingkat kesulitan di sini berasal dari teknik yang dibutuhkan setiap sudoku, bukan dari jumlah angka awal.\"],\"JrrSQM\":[\"Apa bedanya sudoku Pemula dan Mudah?\"],\"Jry7J2\":[\"Sebuah sudoku Pemula dari generator yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"KDXdKh\":[\"Sebuah sudoku Mimpi buruk dari generator yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"KPuUq2\":[\"Tuliskan kandidat setelah sel yang mudah habis\"],\"KQe27c\":[\"Apakah kunci jawaban disertakan?\"],\"KVC9CP\":[\"Buklet Sudoku Pemula cetak adalah PDF gratis berisi sudoku \",[\"clueCount\"],\" angka awal yang setiap sel kosongnya bisa dijangkau dengan sel kosong terakhir atau tunggal telanjang — properti yang diperiksa untuk setiap sudoku sebelum masuk ke PDF. Inilah buklet untuk diberikan kepada pemain pertama kali, kelas yang baru belajar aturan, atau siapa pun yang menginginkan sudoku yang tidak pernah menuntut tebakan kedua.\"],\"KiwVTj\":[\"Apakah Suuudokuuu menyediakan versi cetak besar dari buklet ini?\"],\"Kmcrz2\":[\"Ya. \",[\"SITE_NAME\"],\" gratis dan sumber terbuka, tanpa pembelian dalam aplikasi, langganan, atau tingkat kesulitan berbayar.\"],\"L0XezG\":[\"Apa yang membuat sudoku Neraka\"],\"L36iW5\":[\"Ya. Kode Suuudokuuu, termasuk generator di balik sudoku ini, bersumber terbuka di bawah lisensi MIT, dan situs ini tidak membatasi pencetakan atau pendistribusian ulang PDF — termasuk membagikannya di kelas, sesi les, atau paket lembar kerja.\"],\"L3TeBG\":[\"Seberapa sulit sudoku Pemula?\"],\"LBVuWJ\":[\"Sudoku Pemula\"],\"LDOq68\":[\"Berapa banyak sudoku dalam PDF sudoku Mimpi buruk cetak?\"],\"LI4SwS\":[\"Apa yang membuat sudoku Sedang\"],\"LNoRL7\":[\"<0>Mudah.</0> Menambahkan tunggal tersembunyi, tetap tanpa perlu mencatat kandidat.\"],\"LfQJwZ\":[\"Halaman sampul menyebutkan jumlah sudoku dan halaman di awal, lalu \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman sehingga satu lembar memuat \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" grid lengkap. Halaman terakhir memuat setiap grid yang sudah terselesaikan dengan tata letak yang sama, jadi memeriksa jawaban tidak berarti mencari-cari di format halaman yang berbeda. Seluruh berkas ini berupa grafik vektor dan font PDF standar, sehingga tercetak jernih di ukuran apa pun yang didukung printer. Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku Mudah dengan SE \",[\"seRatingRange\"],\" — angka yang diukur langsung oleh <0>panduan peringkat kesulitan sudoku</0>, bukan sekadar diasumsikan.\"],\"LrHydF\":[\"Baca <0>panduan cara bermain</0> untuk tiga aturan dan penjelasan langkah-langkah pertama Anda, atau cari istilah apa pun di <1>glosarium sudoku</1>, yang mendefinisikan setiap teknik dan setiap kosakata yang dipakai panduan ini.\"],\"Lxq-zS\":[\"Sudoku Cetak Besar\"],\"M1Yfw6\":[\"Minimal satu <0>tunggal tersembunyi</0> per sudoku, di atas sel kosong terakhir dan tunggal telanjang yang sudah dipakai Pemula, dan tidak ada yang lebih sulit.\"],\"MLFx1h\":[\"Ya. Mudah adalah tingkat sumber untuk PDF cetak besar, dengan sampel \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudoku dengan sel lebih besar bagi pembaca yang menginginkan ruang menulis lebih lega.\"],\"MREaAq\":[\"Semua yang dibutuhkan Sedang, ditambah minimal satu pola fish atau wing: X-Wing, swordfish, jellyfish, varian finned dan sashimi-nya, XY-Wing, XYZ-Wing, atau W-Wing. Salah satunya selalu diperlukan, karena sudoku yang tidak membutuhkannya dinilai Sedang.\"],\"MVYMfh\":[\"Tingkat kesulitan sudoku\"],\"M_zq3f\":[\"FAQ Sudoku Tak Terhingga Cetak\"],\"Mz7rRO\":[\"Periksa setiap baris, kolom, dan kotak yang sembilan selnya sudah terisi delapan, lalu tempatkan angka yang hilang di sel kosongnya.\"],\"N0hmpU\":[[\"clueCount\"],\" angka awal dari 81 sel — hanya satu lebih sedikit daripada Sedang, itulah sebabnya tingkat ini ditentukan oleh teknik yang dibutuhkan, bukan oleh jumlah angka awalnya.\"],\"NQTfla\":[\"FAQ Sudoku Pemula Cetak\"],\"NeWjyh\":[\"<0>Pemula</0> — \",[\"newbieClueCount\"],\" angka awal, diselesaikan hanya dengan sel kosong terakhir dan tunggal telanjang.\"],\"NkdmkS\":[\"Teknik apa yang dibutuhkan buklet Mimpi buruk ini?\"],\"Nq65SI\":[\"Tidak. Jumlah angka awal dan tingkat kesulitan adalah dua fakta yang berbeda — lihat <0>panduan sudoku 17 angka awal</0>. Sudoku ini sulit karena masing-masing membutuhkan rantai paksa, bukan karena berapa banyak angka awal yang dimilikinya.\"],\"NuoZju\":[\"Sudah menyelesaikan sudoku Neraka dan ingin lagi? <0>Sudoku Tak Terhingga</0> menyajikan sudoku rekor — Everest, Platinum Blonde, AI Escargot — yang berada di luar jangkauan rantai paksa kami. Belum siap dengan rantai? Mundurlah ke <1>Sudoku Mimpi Buruk</1>, yang meminta penalaran yang sama dengan lebih banyak bagian grid yang sudah terisi. Lebih suka kertas? Unduh <2>PDF sudoku Neraka cetak</2>. Telusuri <3>indeks teknik</3>, terutama X-Chain, XY-Chain, Pewarnaan Sederhana, dan AIC, <4>panduan cara bermain</4>, <5>panduan sudoku 17 angka awal</5>, setiap tingkat di hub <6>Tingkat kesulitan sudoku</6>, atau kembali ke <7>beranda</7>.\"],\"Nyd-0x\":[\"Berapa banyak angka awal sudoku Sulit?\"],\"NzFVBG\":[\"Mengapa fish atau wing lebih mudah diverifikasi di kertas?\"],\"OMs2n2\":[\"Siap merangkai eliminasi alih-alih mengenali bentuk? Naiklah ke <0>Sudoku Mimpi buruk</0>, atau mundur ke <1>Sudoku Sedang</1> untuk sudoku irisan dan subset. Lebih suka kertas? Unduh <2>PDF sudoku Sulit cetak</2>. Lihat <3>indeks teknik</3>, <4>panduan cara bermain</4>, setiap tingkat di hub <5>Tingkat kesulitan sudoku</5>, atau kembali ke <6>beranda</6>.\"],\"OubwsB\":[\"Berapa banyak sudoku dalam PDF sudoku Pemula cetak?\"],\"P2bU2d\":[\"Apa yang membuat sudoku Mudah\"],\"P6JVwt\":[\"Jarang. Kebanyakan pemain bisa melacak beberapa kandidat yang dibutuhkan tunggal tersembunyi di kepala, tetapi menuliskannya tidak ada ruginya pada baris yang lebih ramai.\"],\"PDbaU0\":[\"Apakah saya perlu catatan pensil untuk sudoku Pemula?\"],\"PFKt-9\":[\"Sulit turun ke \",[\"clueCount\"],\" angka awal, dan ini adalah buklet cetak pertama di situs ini yang tidak bisa diselesaikan sampai akhir hanya dengan subset. Setiap sudoku di dalamnya diuji dengan solver yang sudah menguasai setiap irisan dan setiap subset, dan hanya disimpan karena solver itu buntu. Yang menyelesaikannya adalah fish atau wing: <0>X-Wing</0> beserta kerabatnya yang lebih besar dan finned, atau salah satu pola wing bivalue.\"],\"PGxh1d\":[\"Apa itu fish finned dalam sudoku?\"],\"PKS4Or\":[\"Apakah PDF sudoku Tak Terhingga cetak gratis?\"],\"PYziuK\":[\"Rantai tidak punya bentuk tetap dan dibangun tautan demi tautan, yang jauh lebih mudah dilacak dengan menuliskan setiap tautan kuat dan lemah daripada menggulir layar kecil.\"],\"PZQD8F\":[\"Main sekarang\"],\"Pbm-BS\":[\"Bagaimana Suuudokuuu menjamin teknik yang dibutuhkan setiap tingkat?\"],\"PdMLK1\":[\"Everest karya Arto Inkala (2012), 21 angka awal, dipublikasikan dengan SE 11,9.\"],\"Pg0uLs\":[\"Setiap tingkat gratis dimainkan, tanpa iklan dan tanpa pendaftaran. <0>Mainkan sudoku sekarang</0> di salah satu dari tujuh tingkat, atau baca rincian lengkap jumlah angka awal dan teknik yang dibutuhkan di hub <1>Tingkat kesulitan sudoku</1>. Belajar di kertas? Mulailah dengan <2>PDF sudoku Pemula cetak</2>.\"],\"PgRaz8\":[\"Mainkan Sudoku Mudah sekarang\"],\"PivQ2i\":[\"Sangat. Setiap sudoku di kumpulan Tak Terhingga memiliki peringkat SE terpublikasi minimal \",[\"lowestRatingLabel\"],\", jauh melampaui apa pun yang dihasilkan tingkat buatan atau korpus Neraka. Penilai kami sendiri berhenti menilai tangga SE di \",[\"SE_RATING_CEILING\"],\", jadi angka yang dikutip di sini berasal dari penilai independen, dan mesin teknik kami tidak bisa menyelesaikan satu pun grid ini sendirian. Bersiaplah membutuhkan rantai paksa dan jaring paksa yang panjang, dan bersiaplah satu sudoku memakan waktu jauh lebih lama daripada apa pun di situs ini.\"],\"Pqhtap\":[\"Mudah\"],\"PrxlWP\":[\"FAQ Sudoku Mudah Cetak\"],\"PszyWW\":[\"Apa cara tercepat untuk menjadi lebih mahir bermain Sudoku?\"],\"PzS0uu\":[\"Sudoku Sulit memiliki \",[\"clueCount\"],\" angka awal dan dijamin membutuhkan minimal satu pola fish atau wing di atas semua subset.\"],\"Q5B0cW\":[\"Neraka\"],\"QBE_L9\":[\"<0>Mimpi buruk.</0> Selalu buntu di fish dan wing, dan selalu terpecahkan dengan logika rantai atau pewarnaan.\"],\"Qo4hE6\":[\"Rantai mengikuti urutan tautan kuat dan lemah yang berselang-seling di antara kandidat, dimulai dari satu ujung dan bernalar ke arah luar sampai kedua ujungnya membuktikan sebuah eliminasi, apa pun ujung yang ternyata benar. X-Chain melakukannya dengan satu angka; XY-Chain menyusuri jalur sel bivalue, dengan angka yang berganti di setiap langkah. Pewarnaan sederhana memberi dua warna bergantian pada jaringan tautan kuat dari satu angka dan menghapus setiap kandidat yang melihat kedua warna itu. AIC menggabungkan semuanya menjadi satu teknik, dengan angka dan jenis tautan yang bercampur sepanjang satu rantai yang tak terputus. Perbedaannya dengan fish atau wing bukan soal kerumitan, melainkan bentuk: wing adalah susunan tetap tiga atau empat sel yang bisa Anda kenali, sedangkan rantai tidak punya ukuran tetap dan harus dibangun langkah demi langkah. Mimpi buruk dibatasi sampai AIC — apa pun yang masih belum terpecahkan berada di luar jangkauan tingkat yang dibuat otomatis.\"],\"R1g33v\":[\"Tanpa sudoku, hanya grid: satu grid 9×9 satu halaman penuh untuk menyalin sudoku dari buku atau koran, ditambah halaman kedua berisi empat grid yang lebih kecil untuk lembar latihan cepat. Berguna bagi guru yang membuat lembar kerja sendiri atau siapa pun yang menyalin sudoku yang ditemukan di suatu tempat tanpa versi yang siap cetak.\"],\"RJUjbN\":[\"Tips menyelesaikan dengan tanda pensil\"],\"RMq7iB\":[\"Fish melihat satu angka di beberapa garis sekaligus. X-Wing adalah yang terkecil: angka yang terbatas pada dua kolom yang sama di dua baris bisa dihapus dari sisa kolom tersebut, karena baris mana pun yang akhirnya menampung angka itu, kolomnya sudah terkunci. <0>Swordfish</0> memperluas gagasan yang sama ke tiga garis dan jellyfish ke empat garis. Varian finned dan sashimi melonggarkan pola dasar dengan mengizinkan satu kandidat tambahan yang tetap mendukung eliminasi yang lebih kecil namun aman setelah diperhitungkan — dan dalam sampel kami varian ini muncul jauh lebih sering daripada bentuk buku teks. Wing bekerja dengan cara berbeda: XY-Wing menghubungkan tiga sel bivalue sehingga kandidat yang dimiliki dua di antaranya bisa dihapus di mana pun keduanya terlihat, XYZ-Wing memberi kandidat itu juga kepada sel pivot, dan W-Wing menghubungkan dua sel bivalue yang sama melalui tautan kuat pada satu angka bersama. Sulit dibatasi sampai W-Wing: sudoku yang masih buntu setelah semua fish dan wing dicoba adalah sudoku Mimpi buruk, bukan Sulit.\"],\"RRGDQM\":[\"Pemula adalah yang termudah dari tujuh tingkat Suuudokuuu, diikuti Mudah, Sedang, Sulit, Mimpi buruk, Neraka, dan Tak Terhingga dengan kesulitan yang meningkat.\"],\"Rj2Y_n\":[\"Grid Infinity paling terkenal punya halamannya sendiri, masing-masing bisa dimainkan, dicetak, dan diselesaikan langkah demi langkah oleh mesin: <0>AI Escargot</0>, <1>Golden Nugget</1>, <2>Platinum Blonde</2>, <3>Everest</3>, <4>Kolk</4> dan <5>Silver Plate</5>.\"],\"Rwv4vE\":[\"Rantai paksa di setiap sudoku, di atas rantai, pewarnaan, fish, wing, dan subset yang sudah dibutuhkan tingkat-tingkat sebelumnya. X-Chain, XY-Chain, Pewarnaan Sederhana, dan AIC akan membawa Anda jauh, tetapi tidak pernah sampai akhir; <0>rantai paksa Nishio</0> biasanya jalan untuk memecahkan kebuntuan.\"],\"SPFeoH\":[\"FAQ Sudoku Sulit Cetak\"],\"ScJ9fj\":[\"Kebijakan privasi\"],\"Sg-BY5\":[\"Jumlah angka awal bukanlah tingkat kesulitan. Itu hanya masukannya: lebih sedikit angka awal berarti lebih sedikit penempatan langsung, sehingga pemecah — manusia maupun mesin — harus memakai lebih banyak teknik bernama sebelum grid bergerak lagi. Suuudokuuu menghapus angka dari grid yang sudah selesai sampai target per tingkat, memverifikasi bahwa hasilnya tetap punya tepat satu solusi, lalu melakukan bagian yang benar-benar menentukan tingkat itu: sudoku diselesaikan dua kali, sekali dengan tangga teknik tingkat di bawahnya dan sekali dengan tangga tingkatnya sendiri, dan hanya disimpan jika penyelesaian pertama gagal dan yang kedua berhasil. Sudoku yang meleset dibuang dan yang baru dibuat. Itulah sebabnya setiap tingkat di atas dinyatakan sebagai jaminan, bukan harapan. <0>Indeks teknik lengkap</0> mencantumkan setiap pola dalam tangga itu, sesuai urutan yang dicoba pemecah. Dalam satu rentang, dua sudoku masih bisa sangat berbeda — <1>angka awal versus kesulitan</1> mengukur persis seberapa besar bedanya.\"],\"Sjq7vw\":[\"Untuk setiap sel kosong yang tersisa, singkirkan semua angka yang sudah dipakai di baris, kolom, dan kotaknya. Jika hanya satu angka yang tersisa, tempatkan angka itu.\"],\"T5khAF\":[\"Mainkan Sudoku Neraka sekarang\"],\"T91vKp\":[\"Main\"],\"TW-b-m\":[\"Tidak. Jumlah angka awal hanyalah masukan yang mendorong solver ke himpunan teknik yang lebih luas; rentang teknik yang diverifikasi generator-lah yang sebenarnya menentukan setiap tingkat. <0>Panduan angka awal versus kesulitan</0> mengukur selisihnya secara langsung.\"],\"T_JQXy\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Sedang dengan SE \",[\"seRatingRange\"],\".\"],\"T_R-Qz\":[\"Utama\"],\"TiHBaL\":[\"Sudoku Sulit adalah tingkat kesulitan yang dimulai dari \",[\"clueCount\"],\" angka awal dari 81 sel dan didefinisikan oleh apa yang tidak bisa diselesaikan solver yang hanya memakai subset: setiap sudoku di tingkat ini sudah dijalankan melalui solver yang dilengkapi setiap irisan dan setiap subset sampai <0>kuad tersembunyi</0>, dan hanya disimpan karena solver itu macet. Yang memecahkan kebuntuan adalah fish — <1>X-Wing</1>, <2>swordfish</2>, <3>jellyfish</3> beserta varian <4>finned</4> dan <5>sashimi</5>-nya — atau wing: <6>XY-Wing</6>, <7>XYZ-Wing</7>, dan <8>W-Wing</8>.\"],\"TqC0fH\":[[\"clueCount\"],\" angka awal dari 81 sel, dan setiap sel kosong bisa dijangkau dengan sel kosong terakhir atau tunggal telanjang.\"],\"U1U2tC\":[\"Berapa banyak angka awal sudoku mudah?\"],\"U2AKxD\":[\"FAQ sudoku cetak\"],\"U9wBFD\":[\"Mudah tetap berada dalam logika teknik tunggal saja, jadi masih ramah pemula. Satu-satunya keterampilan tambahan dibanding Pemula adalah menemukan angka yang tidak muat di tempat lain dalam sebuah unit.\"],\"UF5_iX\":[\"Ukuran teks standar\"],\"UILsns\":[\"Tuliskan kandidat ke sel hanya setelah pemindaian tidak lagi menghasilkan penempatan.\"],\"Umo747\":[\"Tidak pernah dibutuhkan catatan pensil, logika eliminasi, ataupun tebakan.\"],\"Uq9L94\":[[\"clueCount\"],\" angka awal dari 81 sel, jauh di bawah sepertiga grid.\"],\"UveQZj\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Mimpi buruk dengan SE (Sudoku Explainer) \",[\"seRatingRange\"],\", dengan <0/> sebagai langkah tersulit yang paling sering muncul. AIC adalah batas atasnya: setiap sudoku Mimpi buruk bisa diselesaikan dengannya, dan <1>tingkat Neraka</1> dimulai tepat ketika batas itu berakhir, dengan sudoku yang membutuhkan rantai paksa. Sebagian sudoku Neraka itu memiliki angka awal lebih banyak daripada Mimpi buruk, yang merupakan bukti paling jelas di situs ini bahwa jumlah angka awal dan tingkat kesulitan adalah dua fakta yang berbeda. Tabel terukurnya ada di <2>panduan peringkat kesulitan sudoku</2> kami. Secara kualitatif, di sinilah kesulitan tidak lagi soal kecepatan, melainkan soal menjaga seluruh rangkaian implikasi di kepala tanpa kehilangan jejak.\"],\"V9j1Oq\":[\"Tidak. Setiap sudoku di tingkat ini diverifikasi bisa diselesaikan oleh tangga teknik sampai AIC sebelum dirilis, sehingga rantai yang lengkap selalu ada — menemukannyalah pekerjaannya.\"],\"VHv3Qz\":[\"Sudoku Tak Terhingga memiliki \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" angka awal dan diperiksa memiliki solusi tunggal oleh dua algoritma penyelesaian independen.\"],\"VT7jaN\":[\"Sebuah sudoku Neraka dari korpus terverifikasi yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"VUJcE0\":[\"Ya. Setiap sudoku di buklet bisa diselesaikan hanya dengan sel kosong terakhir atau tunggal telanjang, jadi tidak pernah dibutuhkan penandaan kandidat atau logika eliminasi.\"],\"Vmq46x\":[\"Setelah sel kosong terakhir dan tunggal telanjang terasa otomatis, naiklah ke <0>buklet sudoku Mudah cetak</0>, yang menambahkan tepat satu teknik: tunggal tersembunyi. Untuk memainkan sudoku Pemula di layar, kunjungi <1>halaman sudoku pemula</1>. Untuk tangga teknik lengkap dan data terukur di balik klaim ini, lihat <2>indeks teknik</2> dan <3>panduan peringkat kesulitan sudoku</3>.\"],\"W1nEnp\":[[\"clueCount\"],\" angka awal dari 81 sel, sepertiga grid sudah terisi sebelum Anda mulai.\"],\"W8o5ac\":[\"Tingkat lain ditentukan oleh teknik yang dibutuhkan. Tak Terhingga ditentukan oleh reputasi yang terukur: sebuah sudoku hanya memenuhi syarat jika penilai independen telah mempublikasikan peringkat SE \",[\"minimumRatingLabel\"],\" atau lebih tinggi untuknya. Sebagian besar dari \",[\"infinityCorpusSize\"],\" sudoku berasal dari snapshot tahun 2011 dari database sudoku tersulit yang dikelola komunitas penyelesai sudoku; sisanya adalah klasik bernama, diambil dari utas forum dan publikasi tempat sudoku itu pertama kali muncul. Sebelum kumpulan ini dikemas ke dalam aplikasi, solver exact-cover Dancing Links dan solver bitmask sama-sama memastikan bahwa setiap grid memiliki tepat satu solusi.\"],\"W9xBMf\":[\"Pemain baru sebaiknya mulai dari Pemula dan naik satu tingkat demi satu tingkat; setiap langkah menambahkan tepat satu teknik baru dibanding tingkat sebelumnya, sampai Sulit. Lihat dulu <0>panduan cara bermain</0> jika tiga aturan inti masih terasa asing.\"],\"WB-pGD\":[\"Buklet ini mencetak \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku tersulit yang pernah dipublikasikan, diambil dari tingkat Tak Terhingga Suuudokuuu: Everest karya Arto Inkala, AI Escargot, Platinum Blonde, Golden Nugget, dan grid rekor lainnya, masing-masing dengan peringkat SE (Sudoku Explainer) terpublikasi antara \",[\"lowestRatingLabel\"],\" dan \",[\"highestRatingLabel\"],\". Setiap sudoku memiliki tepat satu solusi, dan grid terselesaikan ada di bagian belakang.\"],\"WG8Ftb\":[\"Berapa banyak angka awal sudoku Pemula?\"],\"WTwN7-\":[\"Mainkan \",[\"SITE_NAME\"]],\"WmW-Gm\":[\"Ruang cetak di sini lebih penting daripada di tingkat yang lebih mudah, karena irisan dan pasangan bekerja dengan menandai kandidat di pinggir. \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman dengan ukuran sel penuh, menyisakan cukup ruang di sekitar setiap angka untuk menuliskan angka-angka kecil yang menjadi dasar penalaran irisan atau pasangan. Grid yang sudah terselesaikan menutup berkas sehingga Anda bisa mencocokkan tanda kandidat dengan jawaban yang terkonfirmasi. Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku Sedang dengan SE \",[\"seRatingRange\"],\" — angka yang diukur langsung oleh <0>panduan peringkat kesulitan sudoku</0>, bukan sekadar diasumsikan.\"],\"WrhTzj\":[\"Ya. Setiap buklet tingkat kesulitan dan set cetak besar memuat grid terselesaikan lengkap di halaman terakhir, dibuat oleh solver yang sama yang memverifikasi bahwa setiap sudoku memiliki tepat satu solusi sebelum dirilis.\"],\"WwMVff\":[\"Seberapa sulit sudoku Mimpi buruk?\"],\"XGVJW3\":[\"Glosarium sudoku\"],\"XORYRH\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman, berukuran sedemikian rupa sehingga rantai yang melintasi seluruh grid tetap muat nyaman di satu lembar. Grid terselesaikan lengkap menutup buklet, yang lebih penting di sini daripada di tingkat yang lebih mudah — satu eliminasi yang terlewat di tengah rantai berdampak berantai dengan cepat, dan kunci jawaban cetak akan menangkapnya. Sebaran terukur di balik klaim ini ada di <0>panduan peringkat kesulitan sudoku</0>.\"],\"XpU6Tm\":[\"Mengapa Neraka memakai korpus sudoku tetap alih-alih membuat sudoku baru?\"],\"XzG50N\":[\"Neraka adalah tingkat berbasis teknik tersulit di Suuudokuuu — yang oleh kebanyakan pesaing disebut evil atau extreme. Sudoku Neraka ditentukan oleh penalaran yang dituntutnya, bukan oleh seberapa sedikit angka awalnya: tidak ada sudoku Neraka yang bisa diselesaikan dengan teknik apa pun yang diizinkan Mimpi buruk, jadi setiap sudoku membutuhkan rantai paksa. Berbeda dengan tingkat yang dibuat otomatis, Neraka diambil dari korpus bawaan berisi sudoku sulit yang pernah dipublikasikan, diverifikasi oleh dua solver independen sebelum dirilis, dan setiap sudoku tetap bisa diselesaikan pada tangga teknik kami tanpa menebak. Bersiaplah memakai setiap pola rantai dan pewarnaan lebih dulu — <0>X-Chain</0>, <1>XY-Chain</1>, <2>pewarnaan sederhana</2>, dan <3>AIC</3> — sebelum rantai paksa memecahkan kebuntuan.\"],\"Y3fLpk\":[\"Berapa banyak sudoku dalam PDF sudoku Sulit cetak?\"],\"YGCzAJ\":[\"Setiap sudoku kandidat diselesaikan dua kali: sekali dengan tangga teknik tingkat di bawahnya, yang harus gagal, dan sekali dengan tangganya sendiri, yang harus berhasil. Sudoku yang gagal di salah satu ujian dibuang dan dibuat ulang.\"],\"YM-Le2\":[[\"clueCount\"],\" angka awal dari 81 sel, dijamin membutuhkan minimal satu teknik rantai atau pewarnaan di atas semua fish dan wing.\"],\"Y_LLdr\":[\"Apakah PDF sudoku Mudah cetak gratis?\"],\"Yj1j4Z\":[\"Sudoku 1 dari buklet Neraka, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"YjxNca\":[\"Mainkan Sudoku Tak Terhingga sekarang\"],\"Z-7bqV\":[\"FAQ Sudoku Sulit\"],\"Z9Mfy1\":[\"Isi buklet\"],\"Z9MhMF\":[\"Apa yang membuat sudoku Pemula\"],\"ZBT6Lr\":[[\"infinityCorpusSize\"],\" sudoku rekor dengan \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" angka awal, dipublikasikan dengan peringkat SE \",[\"lowestRatingLabel\"],\" sampai \",[\"highestRatingLabel\"],\".\"],\"ZPXer3\":[\"Catatan dan kandidat\"],\"Zm7CE_\":[\"Setiap teknik yang dipakai \",[\"SITE_NAME\"],\" untuk membuat petunjuk didokumentasikan dengan contoh papan yang diambil langsung dari mesin penyelesaian. Mulailah dengan <0>indeks teknik lengkap</0>, atau langsung ke salah satu pola pertama yang dipelajari kebanyakan pemain.\"],\"ZtZST0\":[\"Setiap sudoku membutuhkan rantai paksa, diambil dari korpus Neraka kami yang bawaan dan terverifikasi. Lihat <0>halaman sudoku neraka</0> untuk memainkannya secara digital.\"],\"_4AR-Z\":[[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" halaman\"],\"_YA7YX\":[\"Ya, bersama Everest, Platinum Blonde, dan Golden Nugget. Buklet mencetak sudoku sebagaimana dipublikasikan aslinya.\"],\"_kK7k_\":[\"Apa bedanya wing dan rantai?\"],\"_nkVQD\":[\"Tidak ada sudoku di buklet ini yang membutuhkan rantai — itu dimulai di tingkat Mimpi buruk.\"],\"_t9fa1\":[\"Apa itu sudoku Tak Terhingga?\"],\"a3pVqb\":[\"Pertanyaan yang sering diajukan\"],\"aF08Xt\":[\"Tujuh. Pemula, Mudah, Sedang, Sulit, Mimpi buruk, dan Neraka membentuk tangga teknik, masing-masing ditentukan oleh jumlah angka awal dan rentang teknik yang dijamin, bukan label pemasaran. Tak Terhingga berada di atasnya, kumpulan pilihan sudoku rekor yang dipilih berdasarkan peringkat terpublikasi.\"],\"aIDRsS\":[\"<0>Sedang.</0> Selalu buntu di teknik tunggal dan selalu terpecahkan dengan irisan dan subset — pasangan penunjuk, reduksi kotak-baris, pasangan hingga kuad telanjang dan tersembunyi.\"],\"aMv0h8\":[\"Sebuah sudoku Sedang dari generator yang sama dengan yang dipakai aplikasi. Mainkan langsung di sini.\"],\"aOHWJD\":[\"<0>Tunggal Telanjang</0> — sel yang hanya menyisakan satu kandidat.\"],\"aQ3vvP\":[[\"nightmareClueCount\"],\" angka awal, dijamin buntu di wing dan baru terpecahkan dengan rantai dan pewarnaan. Lihat <0>halaman sudoku mimpi buruk</0> untuk memainkannya secara digital.\"],\"aeZiiA\":[\"Setiap sudoku dijamin memiliki tepat satu solusi, tanpa perlu menebak\"],\"agPptk\":[\"Sedang\"],\"ajKnoT\":[\"Tiga aturan Sudoku\"],\"alOHPr\":[\"Siap agar irisan dan subset mulai berperan? Lanjutlah ke <0>buklet sudoku Sedang cetak</0>, atau mundur ke <1>sudoku pemula cetak</1> untuk grid yang lebih ringan. Untuk memainkan sudoku Mudah di layar, kunjungi <2>halaman sudoku mudah</2>.\"],\"bIMckF\":[\"PDF standar sudah memakai tata letak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" sudoku per halaman yang lega. Untuk sel yang lebih besar, lihat <0>buklet sudoku Mudah cetak</0>, yang juga merupakan tingkat sumber PDF cetak besar kami.\"],\"bJo3n2\":[\"Tips sudoku\"],\"bLowF0\":[\"Menyelesaikan sel pertama Anda\"],\"bMqX8c\":[\"Periksa unit yang kekurangan angka\"],\"bQP2nt\":[\"Menyelesaikan sudoku Mudah tanpa memakai tunggal tersembunyi? Mundurlah ke <0>Sudoku Pemula</0>, atau naiklah ke <1>Sudoku Sedang</1>, tempat irisan dan pasangan pertama Anda muncul. Lebih suka kertas? Unduh <2>buklet sudoku Mudah cetak</2>, atau lihat panduan <3>sudoku untuk lansia</3> untuk opsi cetak besar dan kenyamanan. Lihat <4>indeks teknik</4> lengkap, panduan <5>cara bermain</5>, atau setiap tingkat di hub <6>Tingkat kesulitan sudoku</6>, atau kembali ke <7>beranda</7>.\"],\"bUGU7d\":[\"Ukuran dan bentuk. Wing adalah pola tetap tiga atau empat sel yang bisa dikenali sekilas; rantai dibangun tautan demi tautan dan bisa sepanjang apa pun, itulah sebabnya rantai berada satu rentang penuh di atas wing pada skala SE.\"],\"bVG9Tb\":[\"Siap cetak\"],\"bY8tm0\":[\"Kode sumber di GitHub\"],\"bc8DGE\":[\"Isi setiap sel kosong dengan angka 1 sampai 9 sehingga tidak ada angka yang berulang dalam satu baris, satu kolom, atau satu kotak 3×3.\"],\"c38U12\":[\"Apa itu pasangan penunjuk?\"],\"c3R2ID\":[\"Sel Kosong Terakhir dan Tunggal Telanjang adalah dua strategi pertama yang dicoba mesin penyelesaian Suuudokuuu di setiap sudoku pada setiap tingkat kesulitan, karena keduanya adalah deduksi yang paling murah diverifikasi. Yang membuat Pemula berbeda adalah tingkat ini didefinisikan sebagai sudoku yang tidak pernah membutuhkan hal lain. Hapus lebih banyak angka dan solver pada akhirnya akan buntu tanpa tunggal tersembunyi, irisan, atau subset, dan generator membuang sudoku semacam itu alih-alih memberinya label Pemula. Jika Anda bisa membaca satu baris dan menyebut satu angka yang hilang darinya, Anda sudah punya semua keterampilan yang diminta sudoku Pemula.\"],\"cK6miM\":[\"Tingkat kesulitan\"],\"cVxfVr\":[\"Tidak. Kedua teknik yang dibutuhkan sudoku Pemula bisa dibaca langsung dari papan, itulah sebabnya keduanya adalah deduksi tercepat dalam game.\"],\"d4hJrp\":[\"Kesulitan lebih tinggi\"],\"d5hiJp\":[\"Mengapa pemain bertahan\"],\"dKAb7E\":[\"Setiap sudoku Neraka membutuhkan rantai paksa: tidak ada yang bisa diselesaikan dengan teknik yang diizinkan Mimpi buruk, sampai AIC.\"],\"dXoieq\":[\"Ringkasan\"],\"do-_4n\":[\"Minimal satu fish (<0>X-Wing</0> beserta kerabatnya yang lebih besar dan finned) atau satu pola wing bivalue, di atas semua irisan dan subset yang sudah dibutuhkan buklet yang lebih mudah.\"],\"dvRtE-\":[\"Tujuh: Pemula, Mudah, Sedang, Sulit, Mimpi buruk, Neraka, dan Tak Terhingga. Sudoku Neraka berasal dari korpus bawaan yang terverifikasi, yang masing-masing membutuhkan rantai paksa, melampaui semua yang diminta Mimpi buruk, dan <0>Tak Terhingga</0> menyajikan sudoku rekor seperti Everest dan AI Escargot.\"],\"dyGlGe\":[\"Set cetak besar memakai logika tingkat Mudah yang sama dengan buklet di atas, tetapi dengan \",[\"PRINTABLE_LARGE_PRINT_PUZZLES_PER_PAGE\"],\" sudoku per halaman, bukan \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\", sehingga setiap sel dan angka tercetak jauh lebih besar. Cocok untuk penyelesai dengan penglihatan lemah, handout kelas yang dibaca dari kejauhan, dan siapa pun yang merasa grid standar terlalu sempit di kertas. Lihat <0>halaman sudoku cetak besar</0> untuk tips mencetak dan alternatif di layar, atau panduan <1>sudoku untuk lansia</1> untuk uraian lengkap yang berfokus pada kenyamanan.\"],\"e0NrBM\":[\"Proyek\"],\"eBV_Xh\":[\"Sudoku Mimpi buruk memiliki \",[\"clueCount\"],\" angka awal dan dijamin membutuhkan minimal satu teknik rantai atau pewarnaan di atas semua fish dan wing.\"],\"eJ9n-i\":[\"Baru mengenal grid-nya? Mulailah dengan <0>panduan cara bermain</0> untuk tiga aturan dan penempatan pertama Anda sebelum memilih tingkat di atas.\"],\"eJum-4\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku di \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" halaman, dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman dengan kunci jawaban di bagian belakang.\"],\"emFA81\":[\"FAQ Sudoku Mimpi buruk Cetak\"],\"enA4B7\":[\"Apakah sudoku Sulit lebih sulit daripada Mimpi buruk?\"],\"eo2JDj\":[\"Buntu di sebuah sudoku?\"],\"eozBux\":[\"Belum tentu. Sudoku Neraka memiliki \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" angka awal, diambil dari korpus bawaan yang diperiksa oleh dua algoritma penyelesaian independen dan disaring menjadi sudoku yang membutuhkan rantai paksa, bukan dibuat baru saat dicetak.\"],\"ev-7sc\":[\"Tidak. Sulit berhenti di W-Wing; Mimpi buruk dimulai tepat di tempat Sulit berhenti dan berlanjut sampai rantai inferensi berselang-seling. Kedua tingkat dipisahkan oleh batas teknik, bukan jumlah angka awal.\"],\"evANQd\":[\"Teknik rantai dan pewarnaan: X-Chain, XY-Chain, pewarnaan sederhana, dan AIC.\"],\"f0OFpM\":[\"<0>Neraka.</0> Selalu buntu di rantai dan AIC, dan selalu membutuhkan rantai paksa, diambil dari korpus bawaan yang terverifikasi.\"],\"fRl01D\":[\"Sudoku cetak\"],\"fUYszb\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku, dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman, lengkap dengan kunci jawaban.\"],\"fY_UvT\":[\"Inilah buklet untuk dicetak bagi kebiasaan harian singkat, bukan sesi panjang: selipkan ke buku catatan, kerjakan satu grid sekali duduk, dan tidak ada kandidat yang perlu ditulis atau pasangan yang perlu dilacak di sepanjang baris. Cocok juga untuk kelas yang baru memperkenalkan aturan, karena satu kelas penuh bisa menyelesaikan sudoku dalam waktu singkat yang sama tanpa ada yang tersendat pada irisan yang belum diajarkan. Tata letak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman tetap menyisakan grid yang cukup besar untuk ditulisi dengan nyaman, bahkan untuk tulisan tangan anak, dan kunci jawaban di bagian belakang berarti guru tidak perlu menyelesaikan lembarnya sendiri untuk memeriksanya.\"],\"fiJRay\":[\"Minimal satu <0>pasangan penunjuk</0>, <1>reduksi kotak-baris</1>, atau pasangan telanjang atau tersembunyi, di atas teknik tunggal yang sudah dipakai buklet yang lebih mudah. Tidak ada yang membutuhkan fish, wing, atau rantai.\"],\"g4WRV6\":[[\"hellCorpusSize\"],\" sudoku terverifikasi dengan \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" angka awal, diambil dari katalog 17 angka awal tdoku dan daftar top1465 magictour, bukan dibuat baru.\"],\"g5Fk5U\":[\"Sulit\"],\"gJOrtn\":[\"Tingkat kesulitan\"],\"gh-p06\":[[\"clueCount\"],\" angka awal dari 81 sel, dijamin buntu di teknik tunggal dan baru terpecahkan dengan irisan atau subset.\"],\"gmWGv_\":[\"Rantai tidak punya bentuk tetap, itulah sebabnya menandainya dengan pensil lebih membantu di sini daripada di tingkat yang lebih mudah.\"],\"gqWp2B\":[\"Rantai tidak punya bentuk tetap: ia dibangun tautan demi tautan, dan satu-satunya cara melacaknya adalah dengan menuliskannya. Di atas kertas Anda bisa menandai setiap tautan kuat dan lemah, mengikuti pola selang-seling sampai ujung yang jauh, dan langsung melihat sel mana yang terlihat oleh kedua ujung. Itu benar-benar merepotkan di layar ponsel yang harus digulir. Ini juga buklet di mana eliminasi yang salah paling parah dampaknya: jika Anda menghapus kandidat yang seharusnya tetap ada, setiap tautan sesudahnya menjadi tidak sah, jadi anggaplah halaman kunci jawaban sebagai titik pemeriksaan sungguhan, bukan formalitas.\"],\"h4IqRM\":[\"Sudah nyaman menemukan irisan dan subset? Naiklah ke <0>Sudoku Sulit</0>, tempat fish atau wing selalu diperlukan, atau turunlah ke <1>Sudoku Mudah</1> untuk mengulang teknik tunggal. Lebih suka kertas? Unduh <2>buklet sudoku Sedang cetak</2>. Telusuri <3>indeks teknik</3>, <4>panduan cara bermain</4>, setiap tingkat di hub <5>Tingkat kesulitan sudoku</5>, atau kembali ke <6>beranda</6>.\"],\"h6WxWJ\":[\"Cocok untuk penyelesaian santai\"],\"h7hJl_\":[\"Seberapa sulit sudoku ini\"],\"hw66JY\":[\"Sudoku 1 dari buklet Mudah, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"i0qMbr\":[\"Beranda\"],\"i7-8lN\":[\"Petunjuk yang memahami teknik dan menyebutkan pola penyelesaian yang tepat, bukan sekadar angka berikutnya\"],\"iDOJbu\":[\"Fish membentang di seluruh baris atau kolom sekaligus, yang lebih mudah dilacak dengan menandai sisa posisi sebuah angka di sepanjang kolom cetak daripada dengan menggulir layar. Wing membutuhkan sudut pandang sebaliknya — beberapa sel bivalue yang terlihat sekilas.\"],\"iEH6te\":[\"<0>Tunggal Tersembunyi</0> — angka yang hanya muat di satu sel dalam sebuah unit.\"],\"iggj45\":[\"Seberapa sulit sudoku Mudah?\"],\"ippIMU\":[\"Sel kosong tambahan dibanding Pemula itu cukup membuat grid berhenti terisi sendiri hanya dari <0>sel kosong terakhir</0>. Setelah penempatan yang jelas habis, sudoku Mudah selalu menyisakan setidaknya satu sel yang hanya bisa maju dengan penalaran tunggal tersembunyi — periksa angka yang hilang di setiap unit terhadap tempat angka itu masih boleh ditempatkan, bukan membaca kandidat langsung dari satu sel. Mesin teknik Suuudokuuu mencoba tunggal tersembunyi di urutan ketiga, tepat setelah sel kosong terakhir dan <1>tunggal telanjang</1>, dan sudoku berperingkat Mudah tidak pernah perlu melangkah lebih jauh dari itu: tidak ada pasangan penunjuk, tidak ada subset, tidak ada yang meminta Anda memegang lebih dari satu unit dalam pikiran sekaligus. Jarak antartingkat sengaja kecil — lebarnya persis satu teknik.\"],\"iu7tUI\":[\"Jalur navigasi\"],\"iuw_bf\":[\"Peringkat kesulitan\"],\"iyTmPq\":[\"Setiap teknik bernama adalah cara yang lebih cepat untuk melacak tumpang tindih baris, kolom, dan kotak yang sama di banyak sel sekaligus.\"],\"j2fzAU\":[\"Peringkat SE adalah nilai yang dipublikasikan penilai independen dan komunitas penyelesai sudoku. Penilai Suuudokuuu sendiri melaporkan \",[\"SE_RATING_CEILING\"],\" dengan tanda batas atas untuk apa pun yang lebih sulit dari itu, jadi tidak menghasilkan angka sendiri untuk sudoku ini.\"],\"j2t1NI\":[\"Setiap tingkat menaut ke halaman lengkap dengan pratinjau sudoku langsung dan fakta kesulitan yang jujur dari <0>panduan peringkat kesulitan sudoku</0> kami. PDF-nya sendiri hanya membutuhkan printer.\"],\"jFRHhT\":[\"<0>Tak Terhingga</0> — \",[\"infinityCorpusSize\"],\" sudoku tersulit yang pernah dipublikasikan, dipilih berdasarkan peringkat SE terpublikasi sebesar \",[\"infinityLowestRating\"],\" sampai \",[\"infinityHighestRating\"],\", bukan rentang teknik, dan di luar jangkauan semua teknik pada tangga kami.\"],\"jJ8CSk\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Sulit dengan SE \",[\"seRatingRange\"],\".\"],\"jMk3uh\":[\"Jangan mencari sel tersulit lebih dulu. Mulailah dengan mencari penempatan yang paling mudah, karena menyelesaikannya lebih dulu membuat setiap sel berikutnya lebih mudah juga.\"],\"jP5seF\":[\"Pelajari teknik berdasarkan urutan kesulitan, bukan dengan menghafal semua pola sekaligus. <0>Indeks teknik sudoku</0> mencantumkannya dari sel kosong terakhir sampai pola subset, masing-masing dengan contoh pengerjaan.\"],\"jmetfY\":[\"Apakah sudoku Mudah pernah membutuhkan catatan pensil?\"],\"juLzrc\":[\"Mudah adalah tingkat pertama tempat Suuudokuuu mengharapkan penyelesaian yang sungguh-sungguh, meski ringan. Sudoku Mudah memiliki \",[\"clueCount\"],\" angka awal dari 81 sel, beberapa lebih sedikit daripada Pemula. Sel kosong terakhir dan tunggal telanjang masih menyelesaikan sebagian besar grid, tetapi tidak pernah seluruhnya: selalu ada setidaknya satu sel yang membutuhkan <0>tunggal tersembunyi</0>, yaitu angka yang hanya muat di satu sel pada sebuah baris, kolom, atau kotak meskipun sel itu masih menampilkan kandidat lain. Satu pola tambahan itulah seluruh peningkatan dari Pemula ke Mudah, dan itu merupakan jaminan, bukan kecenderungan: sudoku yang bisa diselesaikan oleh solver dengan sel kosong terakhir dan tunggal telanjang saja ditolak karena terlalu mudah untuk tingkat ini, dan sudoku yang membutuhkan lebih dari tunggal tersembunyi ditolak karena terlalu sulit.\"],\"jwpEc6\":[\"Setelah penempatan mudah habis, melacak kandidat secara manual menjadi penting. Kandidat, kadang disebut tanda pensil, adalah angka yang masih sah untuk sebuah sel berdasarkan apa yang sudah ada di baris, kolom, dan kotaknya. Menuliskan setiap kandidat di sel — di kertas sebagai angka kecil di sudut, atau dengan mode catatan di aplikasi — mengubah sudoku yang tampak buntu menjadi sudoku yang polanya terlihat: pasangan, tripel, dan kuad kandidat yang berulang di sebuah unit persis yang dirancang untuk ditemukan teknik seperti pasangan telanjang dan pasangan tersembunyi. Metode lengkap untuk setiap pola ada di <0>indeks teknik sudoku</0>, dan setiap istilah yang dipakai dalam panduan ini didefinisikan di <1>glosarium sudoku</1>.\"],\"kFGAW9\":[\"Apakah jumlah angka awal yang sedikit membuat sudoku ini sulit?\"],\"kV-GNp\":[\"<0>Sedang</0> — \",[\"mediumClueCount\"],\" angka awal, dijamin buntu di teknik tunggal dan baru terpecahkan dengan irisan dan subset.\"],\"kbLXsu\":[\"Kunci jawaban ada di halaman terakhir\"],\"kc2u3T\":[\"Coret kandidat sel demi sel\"],\"lAIHWp\":[\"<0>Sulit</0> — \",[\"hardClueCount\"],\" angka awal, dijamin buntu di subset dan baru terpecahkan dengan pola fish dan wing.\"],\"lDdTS6\":[\"FAQ Sudoku Sedang Cetak\"],\"lINilK\":[\"PDF dibuka dengan halaman sampul yang menyebutkan jumlah sudoku dan halaman, dilanjutkan dengan \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku yang dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman, dan ditutup dengan setiap grid terselesaikan di halaman terakhir agar jawaban tidak pernah berada di sebelah sudoku yang belum terselesaikan. Setiap grid digambar dengan garis vektor dan font PDF standar Helvetica, sehingga tetap tajam di ukuran cetak apa pun dan tidak pernah bergantung pada gambar hasil pindai. Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku Pemula dengan SE \",[\"seRatingRange\"],\" — angka yang diukur langsung oleh <0>panduan peringkat kesulitan sudoku</0>, bukan sekadar diasumsikan.\"],\"lPXkj-\":[\"Bisakah buklet Pemula ini dicetak dengan ukuran besar?\"],\"lQAsJI\":[\"<0>Aturan kolom.</0> Setiap dari sembilan kolom harus berisi angka 1 sampai 9, masing-masing tepat satu kali.\"],\"laMpeD\":[\"Mimpi buruk\"],\"llBUQM\":[\"Berfungsi sepenuhnya offline setelah dipasang, di iOS, Android, dan web\"],\"lxRnL8\":[\"<0>Aturan kotak.</0> Setiap dari sembilan kotak 3×3 harus berisi angka 1 sampai 9, masing-masing tepat satu kali.\"],\"lzXj7Z\":[\"Setiap sudoku di buklet ini membutuhkan rantai paksa: tidak ada yang bisa diselesaikan dengan teknik yang diizinkan Mimpi buruk, dan masing-masing diambil dari korpus Neraka kami yang bawaan dan terverifikasi secara independen, bukan dibuat baru. Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku dengan tingkat SE \",[\"seRatingRange\"],\", dengan <0/> sebagai langkah tersulit yang paling sering muncul. Lihat <1>panduan 17 angka awal</1> untuk mengetahui mengapa jumlah angka awal bukan yang membuatnya sulit.\"],\"mDD4iI\":[\"Ya, tanpa akun dan tanpa tanda air, dan grid terselesaikan setiap sudoku disertakan di bagian belakang.\"],\"mOCJOb\":[\"Sudah mencoba beberapa sudoku Mimpi buruk? <0>Sudoku Neraka</0> adalah tingkat terakhir, tempat setiap sudoku membutuhkan rantai paksa. Mundurlah ke <1>Sudoku Sulit</1> jika fish dan wing masih belum meyakinkan. Lebih suka kertas? Unduh <2>buklet sudoku Mimpi buruk cetak</2>. Telusuri <3>indeks teknik</3>, <4>panduan cara bermain</4>, setiap tingkat di hub <5>Tingkat kesulitan sudoku</5>, atau kembali ke <6>beranda</6>.\"],\"mVu64h\":[\"Sudoku Pemula memiliki \",[\"clueCount\"],\" angka awal dan dijamin selesai hanya dengan sel kosong terakhir dan tunggal telanjang.\"],\"m_1uBm\":[\"Sudoku harian\"],\"mbw3Zs\":[\"Tingkat kesulitan apa saja yang ada?\"],\"mdr9O2\":[[\"PRINTABLE_BLANK_GRID_PAGE_COUNT\"],\" halaman\"],\"mf-vQH\":[[\"newbieClueCount\"],\" angka awal, diselesaikan hanya dengan sel kosong terakhir dan tunggal telanjang. Lihat <0>halaman sudoku pemula</0> untuk memainkannya secara digital.\"],\"mqvuZQ\":[\"Belajar menyelesaikan\"],\"n8c99d\":[\"Pemecah sudoku\"],\"ngqvTg\":[\"Tautan sudoku yang bisa dibagikan dan replay game lengkap untuk setiap penyelesaian\"],\"o83Dls\":[\"Sudoku Mudah memiliki \",[\"clueCount\"],\" angka awal dan dijamin membutuhkan minimal satu tunggal tersembunyi dan tidak lebih sulit dari itu.\"],\"o8ErsC\":[\"Bisakah sudoku punya dua solusi?\"],\"oACpQU\":[\"Panduan tingkat kesulitan\"],\"oF5_MF\":[\"Ukuran teks besar\"],\"oFKMy-\":[\"Belum siap dengan rantai di kertas? Mundurlah ke <0>buklet sudoku Mimpi buruk cetak</0> untuk penalaran rantai yang sama dengan lebih banyak bagian grid yang sudah terisi, atau ke <1>sudoku sulit cetak</1> untuk fish dan wing tanpa penalaran sepanjang rantai, atau mainkan Neraka di layar pada <2>halaman sudoku neraka</2>, tempat korpus yang sama menjadi sumber setiap sudoku. Siap untuk sudoku rekor? <3>Buklet sudoku Tak Terhingga cetak</3> mencetak Everest, AI Escargot, dan grid rekor lainnya.\"],\"oH36ji\":[\"Apakah sudoku Tak Terhingga punya solusi tunggal?\"],\"oQ8R9m\":[\"Apakah sudoku Mimpi buruk pernah membutuhkan tebakan?\"],\"oSfAuO\":[\"Sudoku Sedang\"],\"o_ys4H\":[\"Setiap sudoku Pemula dinilai pada skala SE (Sudoku Explainer) begitu dibuat. Sampel terpublikasi kami berisi \",[\"sampleSize\"],\" sudoku Pemula dengan SE \",[\"seRatingRange\"],\" — dasar paling bawah dari skala yang berjalan sampai 12, dan di bawah apa yang bahkan disebut dalam sebagian besar bagan berbasis SE. Pemula ada untuk mengajarkan tumpang tindih baris-kolom-kotak yang menjadi dasar setiap teknik berikutnya, bukan untuk mengujinya. Rentang terukur untuk tingkat ini dan semua tingkat lainnya dipublikasikan di <0>panduan peringkat kesulitan sudoku</0> kami. Anggaplah penyelesaian Pemula yang cepat dan tanpa kesalahan sebagai tanda Anda siap untuk Mudah, bukan tolok ukur yang layak dikejar demi dirinya sendiri.\"],\"oc75Be\":[\"Sudoku yang tersusun baik tidak pernah begitu. Jika sebuah sudoku punya lebih dari satu penyelesaian yang valid, sudoku itu dianggap rusak, karena logika saja tidak lagi bisa menunjuk satu jawaban.\"],\"ohi_6A\":[\"Untuk setiap unit dengan beberapa sel kosong, periksa apakah ada angka yang masih hilang dari unit itu yang hanya muat di salah satunya, meskipun sel itu juga punya kandidat lain.\"],\"p6O9l-\":[\"Berapa banyak sudoku dalam PDF sudoku Tak Terhingga cetak?\"],\"p95wx0\":[\"Sel kosong terakhir dan teknik tunggal sebagai dasar, ditambah pasangan penunjuk, tripel penunjuk, reduksi kotak-baris, dan subset telanjang atau tersembunyi sampai kuad setiap kali teknik tunggal habis. Minimal satu dari semua itu selalu diperlukan, dan tidak pernah ada yang lebih sulit.\"],\"pDFJMU\":[\"Unduh PDF dan buka di aplikasi pembaca PDF mana pun, lalu cetak dengan skala 100% di kertas US Letter. Setiap grid digambar dengan garis vektor dan font PDF standar, jadi tidak ada yang perlu dirasterisasi dan tidak ada penurunan kualitas di ukuran cetak apa pun.\"],\"pIksP6\":[\"FAQ Sudoku Tak Terhingga\"],\"pN5c2M\":[\"Sudoku Mimpi buruk\"],\"pOHwnD\":[\"Teknik apa yang dibutuhkan buklet Sedang ini?\"],\"pXows4\":[\"Suuudokuuu memiliki tujuh tingkat kesulitan: enam yang masing-masing membutuhkan lebih banyak teknik daripada sebelumnya, dan Tak Terhingga.\"],\"pe908p\":[\"Angka awal adalah angka yang sudah tercetak di papan sebelum Anda mulai. Kandidat adalah angka yang masih Anda pertimbangkan untuk sebuah sel kosong, berdasarkan apa yang saat ini tidak mungkin menurut baris, kolom, dan kotaknya.\"],\"plp0e4\":[\"Mainkan Sudoku Mimpi buruk sekarang\"],\"pu3rE1\":[\"Dengan \",[\"clueCount\"],\" angka awal dari 81 sel, buklet ini adalah yang pertama yang layak dikerjakan dengan pensil. Teknik tunggal membawa grid Sedang sampai setengah jalan, tetapi setiap sudoku di dalamnya terbukti buntu di teknik itu — itulah ujian yang harus gagal dilewati setiap sudoku agar bisa dicetak di sini — sampai Anda menemukan <0>pasangan penunjuk</0> atau <1>reduksi kotak-baris</1>, irisan antara kotak dan garis yang hanya menghapus kandidat, tidak pernah langsung menempatkan angka. Tidak ada sudoku di buklet ini yang membutuhkan fish, wing, atau rantai.\"],\"q7QiGX\":[\"Cara bermain\"],\"qcBjCp\":[\"<0>Mimpi buruk</0> — \",[\"nightmareClueCount\"],\" angka awal, dijamin buntu di wing dan baru terpecahkan dengan rantai dan pewarnaan.\"],\"qiqtfW\":[\"Mainkan Sudoku Sedang sekarang\"],\"qrmik6\":[[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudoku\"],\"qwJuVW\":[\"Footer\"],\"qyiPQ_\":[\"Mudah adalah buklet yang dipilih orang ketika ingin menyelesaikan sudoku tanpa perlu berpikir keras — di kereta, saat istirahat minum kopi, atau untuk bersantai sebelum tidur. Setiap deduksi masih bisa dibaca langsung dari papan, bukan dari grid kandidat, jadi nyaris tidak ada alasan menulis kandidat di pinggir; tunggal tersembunyi meminta Anda memindai seluruh unit, bukan satu sel, yang merupakan perubahan kebiasaan dan bukan perubahan kesulitan. Itu membuatnya cocok untuk dicetak beberapa sekaligus dan dikerjakan sedikit demi sedikit sepanjang minggu, karena tidak ada satu sudoku pun yang menuntut konsentrasi seperti grid Sedang atau Sulit.\"],\"r2FUkM\":[\"Mainkan sudoku ini di sini\"],\"r4WJmT\":[\"Teknik sudoku\"],\"r7ajsb\":[\"Tanpa iklan, tanpa akun, dan tanpa pelacakan di dalam game, baik di web maupun di aplikasi\"],\"r8BZnz\":[\"Apakah saya perlu pulpen dan kertas untuk menyelesaikan sudoku?\"],\"rFkWoz\":[\"Tidak. Setiap sudoku yang dibuat Suuudokuuu diperiksa memiliki solusi tunggal saat dibuat, jadi tidak ada sel yang membutuhkan tebakan — dan sudoku tingkat Neraka bawaan juga diperiksa silang oleh dua algoritma penyelesaian independen, solver exact-cover Dancing Links dan solver bitmask, sebelum dirilis. Posisi yang tampak ambigu hanya membutuhkan teknik yang belum dicoba.\"],\"rISE1w\":[\"Teknik apa yang saya butuhkan untuk sudoku Sedang?\"],\"rUmdf8\":[\"Apakah PDF sudoku Sulit cetak gratis?\"],\"rUv2wg\":[\"Juga merupakan tingkat sumber untuk PDF cetak besar, dengan sampel \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudoku.\"],\"rcYOQY\":[\"Minimal satu teknik rantai atau pewarnaan — fish setingkat <0>swordfish</0> dan wing setingkat <1>XY-Wing</1> saja tidak cukup — di atas semua fish dan wing yang sudah dibutuhkan tingkat Sulit.\"],\"rgh2Sh\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Mimpi buruk dengan SE \",[\"seRatingRange\"],\".\"],\"rhRptr\":[\"Ini lompatan nyata dari Mudah, tetapi setiap teknik yang dibutuhkannya masih bekerja di dalam satu kotak atau satu garis sekaligus — pola fish dan rantai yang lebih panjang baru dimulai dari Sulit ke atas.\"],\"rjZpLn\":[\"Belajar\"],\"rtx2YX\":[[\"easyClueCount\"],\" angka awal, dan setiap sudoku membutuhkan paling tidak satu tunggal tersembunyi, tidak lebih. Lihat <0>halaman sudoku mudah</0> untuk memainkannya secara digital.\"],\"sAlGDx\":[\"Gratis, sumber terbuka, tanpa iklan\"],\"sMgCJW\":[\"Sudoku yang membutuhkan tunggal tersembunyi atau teknik yang lebih sulit akan ditolak dan dibuat ulang, tidak pernah diberi label Pemula.\"],\"sYhvIH\":[\"<0>Tak Terhingga.</0> Sudoku tersulit yang pernah dipublikasikan, seperti Everest dan AI Escargot, dipilih berdasarkan peringkat yang dipublikasikan, bukan rentang teknik — lihat <1>halaman Tak Terhingga</1>.\"],\"sf_Uq_\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Pemula dengan SE \",[\"seRatingRange\"],\".\"],\"sgcKNN\":[\"Setiap aturan Sudoku sebenarnya adalah batasan yang sama yang diterapkan pada tiga jenis unit. Pelajari batasan itu sekali dan Anda sudah tahu ketiga aturannya.\"],\"sjwplg\":[\"Setiap buklet di bawah ini adalah PDF sudoku cetak gratis yang dibuat dari sumber sudoku yang sama dengan yang dimainkan aplikasi — generator dan pendeteksi tekniknya, dan untuk Neraka dan Tak Terhingga, korpus bawaannya yang terverifikasi. Pilih tingkat kesulitan untuk mendapatkan buklet berisi \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dengan kunci jawaban di halaman terakhir, atau ambil set cetak besar atau grid sudoku kosong di bawah. Tanpa pendaftaran, tanpa iklan, tanpa tanda air.\"],\"ssPRl9\":[\"Tingkat tersulit Suuudokuuu: \",[\"infinityCorpusSize\"],\" sudoku tersulit yang pernah dipublikasikan, masing-masing dengan peringkat SE terpublikasi \",[\"minimumRatingLabel\"],\" atau lebih, bisa dimainkan gratis tanpa iklan.\"],\"svA7xQ\":[\"Siap untuk sudoku yang membutuhkan satu gagasan lagi? Naiklah ke <0>Sudoku Mudah</0>, yang menambahkan tunggal tersembunyi di atas semua yang ada di sini. Lebih suka kertas? Unduh <1>buklet sudoku Pemula cetak</1>, atau lihat panduan <2>sudoku untuk lansia</2> untuk opsi cetak besar dan kenyamanan. Telusuri <3>indeks teknik</3> lengkap atau <4>panduan cara bermain</4>, atau kembali ke <5>beranda</5> dan lihat ketujuh tingkat di hub <6>Tingkat kesulitan sudoku</6>.\"],\"tHJbOh\":[\"Apakah Tak Terhingga lebih sulit daripada Neraka?\"],\"tK6SRc\":[\"Setiap sudoku membutuhkan rantai paksa, diambil dari korpus bawaan yang terverifikasi secara independen dengan \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" sampai \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" angka awal.\"],\"tYB68O\":[\"Sudoku 1 dari buklet Tak Terhingga, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"tc4WHX\":[\"Apakah jumlah angka awal yang lebih sedikit selalu berarti sudoku yang lebih sulit?\"],\"thMLRg\":[\"Sulit dibatasi sampai W-Wing — sudoku yang bertahan melawan semua fish dan wing dinilai Mimpi buruk.\"],\"uFeI93\":[\"Setiap permainan mengacak ulang grid, sehingga sudoku rekor yang sudah Anda kenal tidak pernah terlihat sama dua kali.\"],\"uJerz5\":[\"Suuudokuuu menilai sudokunya pada tangga enam tingkat, dari Pemula sampai Neraka, dan setiap tingkat ditentukan oleh dua fakta konkret, bukan label pemasaran: berapa banyak angka awal di grid, dan teknik penyelesaian bernama apa yang dijamin dibutuhkan tingkat itu. Setiap sudoku baru juga dinilai pada skala SE (Sudoku Explainer) begitu dibuat, oleh paket penilai sumber terbuka yang sama yang dipakai <0>panduan peringkat kesulitan sudoku</0> untuk mempublikasikan rentang teknik dan rentang SE terukur dari setiap tingkat tangga di bawah. Di atas tangga ada <1>Tak Terhingga</1>, kumpulan pilihan sudoku rekor yang membawa peringkat yang dipublikasikan penilai independen, karena sudoku itu melampaui puncak skala penilaian kami sendiri.\"],\"uy5vQS\":[\"Ketik atau tempel grid ke <0>pemecah sudoku langkah demi langkah</0> dan ia akan menyebutkan setiap langkah — Tunggal Tersembunyi, Pasangan Telanjang, X-Wing — alih-alih langsung mengisi papan. Ia memeriksa dulu bahwa sudoku Anda memiliki tepat satu solusi, dan berjalan sepenuhnya di peramban Anda.\"],\"uyJsf6\":[\"Tentang\"],\"v1_ToA\":[\"Irisan dan pasangan ditemukan dengan menandai setiap kandidat yang tersisa dalam sebuah unit, jadi tata letaknya menyisakan ruang di setiap sel khusus untuk catatan pensil itu.\"],\"vAJFgP\":[\"Cocok untuk membangun kebiasaan bermain sudoku\"],\"vEHxJQ\":[\"Tingkat kesulitan sudoku\"],\"vLhN57\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Sulit dengan SE (Sudoku Explainer) \",[\"seRatingRange\"],\" — tepat di rentang yang oleh komunitas penyelesai dikaitkan dengan pola fish dan wing, dan jauh di bawah wilayah rantai di atas 7. Langkah tersulit yang paling sering muncul adalah <0/>, dan yang tersulit yang pernah dicapai dalam sampel adalah <1/>. Di sinilah pemain santai mulai meminta petunjuk: fish dan wing mudah dijelaskan tetapi benar-benar sulit dilihat pada papan langsung, jadi bersiaplah untuk penyelesaian yang jelas lebih lama dan lebih cermat daripada yang diminta Sedang. Lihat <2>panduan peringkat kesulitan sudoku</2> untuk data lengkap per tingkat.\"],\"vNl4Yu\":[\"Mudah dimulai dari \",[\"clueCount\"],\" angka awal, enam lebih sedikit daripada Pemula, dan menambahkan tepat satu teknik: setiap sudoku di buklet ini membutuhkan minimal satu <0>tunggal tersembunyi</0>, dan tidak ada yang membutuhkan yang lebih sulit. Satu pola tambahan itulah yang menjadikannya buklet yang dicetak untuk penyelesaian santai saat istirahat kopi, bukan alat bantu belajar. Ini juga tingkat sumber untuk PDF cetak besar kami, dengan sampel \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" sudoku untuk pembaca yang menginginkan sel lebih besar.\"],\"vXIe7J\":[\"Bahasa\"],\"vbOpg_\":[\"Mengapa \",[\"SITE_NAME\"]],\"viJ4-_\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Neraka dengan SE \",[\"hellSeRatingRange\"],\".\"],\"vlNS-q\":[\"Pemula adalah tingkat pemula Suuudokuuu, pengenalan paling lembut ke grid. Sudoku Pemula dimulai dengan \",[\"clueCount\"],\" dari 81 sel sudah terisi. Setiap sel yang tersisa bisa ditemukan dengan dua deduksi paling sederhana dalam game: <0>sel kosong terakhir</0>, ketika sebuah unit tinggal menyisakan satu sel kosong, dan <1>tunggal telanjang</1>, ketika baris, kolom, dan kotak sebuah sel sudah mencakup delapan dari sembilan angka. Ini bukan gambaran sudoku Pemula yang umum — ini aturan yang ditegakkan generator: sudoku kandidat hanya diterima sebagai Pemula setelah solver yang dibatasi pada sel kosong terakhir dan tunggal telanjang berhasil menyelesaikannya. Tidak pernah dibutuhkan catatan pensil, logika eliminasi, ataupun tebakan.\"],\"voLlG5\":[\"Cara mulai menyelesaikan sudoku\"],\"vsge_o\":[\"Baru mengenal Sudoku?\"],\"vvCT_r\":[\"Langkah selanjutnya\"],\"vwz0Q4\":[[\"fileSizeKilobytes\"],\" KB PDF, US Letter\"],\"wIwe3l\":[\"Bagaimana tangga ini disusun\"],\"wT9V53\":[\"Sedang adalah tingkat pertama tempat Suuudokuuu mulai meminta catatan pensil. Sudoku Sedang memiliki \",[\"clueCount\"],\" angka awal dari 81 sel, dan teknik tunggal saja terbukti tidak pernah menyelesaikannya: setiap sudoku di tingkat ini diperiksa dengan solver yang hanya memakai teknik tunggal dan ditolak jika solver itu berhasil menyelesaikannya. Setelah sel kosong terakhir dan teknik tunggal habis, sudoku akan buntu sampai Anda menemukan irisan — angka yang terbatas pada tempat kotak dan garis bertumpang tindih — atau pasangan yang saling terkunci. <0>Pasangan penunjuk</0>, <1>tripel penunjuk</1>, dan <2>reduksi kotak-baris</2> mencakup irisan; <3>pasangan telanjang</3> dan <4>pasangan tersembunyi</4> mencakup pola subset terkecil.\"],\"xI2Au1\":[\"Sudoku 1 dari buklet Sulit, satu dari \",[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku dalam PDF.\"],\"xRTkBI\":[\"Tak Terhingga\"],\"xTziZu\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku di \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" halaman, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" sudoku per halaman, dengan kunci jawaban di bagian belakang.\"],\"xYaf-9\":[\"Apakah Neraka lebih sulit daripada Mimpi buruk?\"],\"xkW-Mi\":[\"Mengapa buklet ini menyisakan lebih banyak ruang di sekitar setiap angka?\"],\"xs4NvR\":[\"Apakah \",[\"SITE_NAME\"],\" gratis?\"],\"y-GOTe\":[\"Setelah itu, perhatikan satu sel kosong dan coret setiap angka yang sudah muncul di baris, kolom, dan kotaknya. Jika hanya satu angka yang tersisa, itulah <0>tunggal telanjang</0>, dan bisa langsung ditempatkan. Jika sebuah sel masih punya beberapa kandidat, periksa apakah salah satu kandidat itu tidak bisa ditempatkan di tempat lain dalam unit yang sama — itulah <1>tunggal tersembunyi</1>, yang sama amannya untuk ditempatkan. Kedua pola ini bersama-sama menyelesaikan sebagian besar sudoku mudah tanpa penalaran yang lebih dalam.\"],\"yDLr5P\":[\"Sudoku cetak besar\"],\"yNzy3T\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Sedang dengan SE \",[\"seRatingRange\"],\", dan \",[\"singlesOnlyPuzzleCount\"],\" dari \",[\"sampleSize\"],\" selesai hanya dengan teknik tunggal — ini adalah tingkat pertama yang angkanya nol secara konstruksi. Langkah tersulit yang paling sering muncul dalam sampel adalah <0/>, dan yang tersulit yang pernah dicapai adalah <1/>. Pemain yang lancar membaca tanda pensil menyelesaikan sudoku Sedang jauh lebih cepat daripada pemain yang mengandalkan pelacakan kandidat di kepala, yang akan mendapati ini tingkat pertama yang benar-benar menghargai kebiasaan menuliskan kandidat. Data lengkap per tingkat ada di <2>panduan peringkat kesulitan sudoku</2> kami.\"],\"y_3zNL\":[\"Sel kosong terakhir dan tunggal telanjang masih menyelesaikan sebagian besar grid; tunggal tersembunyi adalah satu-satunya tambahan dibanding Pemula.\"],\"yjTW_5\":[\"Teknik apa yang saya butuhkan untuk tingkat Neraka?\"],\"yy8xD2\":[\"Grid itu sendiri tidak pernah berubah: sembilan baris, sembilan kolom, dan sembilan kotak, total delapan puluh satu sel. Yang berubah dari satu sudoku ke sudoku lain hanyalah sel mana yang terisi di awal dan angka apa yang dikandungnya, dan tata letak awal angka-angka awal itulah yang menentukan seberapa banyak logika yang dibutuhkan untuk mencapai satu solusi yang valid.\"],\"z0P0h9\":[\"Sampel kami berisi \",[\"sampleSize\"],\" sudoku Neraka dengan SE (Sudoku Explainer) \",[\"hellSeRatingRange\"],\", dengan <0/> sebagai langkah tersulit yang paling sering muncul dan <1/> sebagai langkah tersulit yang pernah dicapai dalam sampel. Hati-hati jangan menganggap jumlah angka awal sebagai penyebabnya: sampel yang sama menempatkan <2>Mimpi buruk</2> pada SE \",[\"nightmareSeRatingRange\"],\" dengan \",[\"nightmareClueCount\"],\" angka awal, dan sebagian sudoku Neraka dimulai dengan angka awal yang lebih banyak dari itu. Tingkat ini dulu dibuat hanya dari sudoku 17 angka awal, dan peringkatnya tidak lebih sulit daripada Mimpi buruk; memilih berdasarkan teknik yang dibutuhkan itulah yang memisahkan keduanya. <3>Panduan angka awal versus kesulitan</3> kami membahas argumen itu dengan tuntas, dan <4>panduan peringkat</4> mempublikasikan tabel per tingkat.\"],\"zGCYA8\":[\"Bisakah saya memainkan AI Escargot dan Everest di sini?\"],\"zX6n8C\":[\"Sudoku rekor seperti Everest dan AI Escargot, dicetak sebagaimana dipublikasikan aslinya. Lihat <0>halaman sudoku tak terhingga</0> untuk memainkannya secara digital.\"],\"zaRGXY\":[\"Grid sudoku kosong\"],\"zdhNJO\":[\"FAQ Sudoku Sedang\"],\"zu-XZL\":[\"Sudoku Mudah\"],\"zuuvDj\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" sudoku rekor, dicetak \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" per halaman, lengkap dengan kunci jawaban.\"]}")as Messages;